local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[26466] = { id = 26466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to their ancient locks.\n\nThat key is a ring, the Ring of Zoram. It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on her isle on the northern edge of the Zoram Strand. Please, {name}, retrieve the ring for me!", progress = "It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, {name}?", completion = "You found the ring! Thank you, {name}.\n\nPlease take this as payment, and know that your deeds today will remain forever in my memory.", objectives = "Obtain the Ring of Zoram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26467] = { id = 26467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n{name}, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", completion = "Judging by the gaping wound in her side, Anilia is on the verge of death.", objectives = "Find Anilia at Xavian in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26468] = { id = 26468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over...", objectives = "Obtain the Branch of Cenarius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26469] = { id = 26469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind {race}. My sister's spirit is gladdened by your efforts.", objectives = "Obtain 16 Satyr Horns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26470] = { id = 26470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking Mystral Lake", description = "We could easily have held Silverwind Refuge from the Horde had they not taken control of our water elemental defenders on Mystral Lake.\n\nOne of their shaman summoned in Tideress, an old and angry water spirit of the forest who befouled our elementals and turned them against us. With the lake and the Horde pressing in on us, we had no choice but to retreat to the spire here.\n\nGo east. Take the lake back so that we will have a chance to retake the refuge some day.", completion = "Well done, {name}! With the befouled elemental numbers thinned and Tideress put back into the lake, we should be able to launch a counter-offensive on Silverwind Refuge.\n\n\n\nJust as soon as we're done with defending the spire....", objectives = "Slay 12 Befouled Water Elementals and Tideress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26471] = { id = 26471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "It is my duty to collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in to the west. That place is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript. Do this, and I will not forget it. Not even in these end days.", objectives = "Bring the Lorgalis Manuscript to Sentinel-trainee Issara at the Blackfathom Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26472] = { id = 26472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insane Druids", description = "The druids are dead, killed by their leaders who were driven insane by the Horde tainting the Forest Heart! I can feel the corruption even from here and I dare go no further.\n\nWhile I am too well attuned to Ashenvale and the Forest Heart, you... you could descend into the barrow den and do what must be done. I've laid down breadcrumbs for you in there.\n\nThough it tears me apart, I must ask that you put to rest the druids' once great leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", completion = "Rest in peace, my friends.\n\n<You can see the sorrow in the druid cat's eyes.>\n\nI felt the anguish of the Dor'danil Barrows lessen, and knew that you had completed your task.\n\nIt was grim work that you did, {name}, for the spirits you destroyed were merely victims of the Horde's evil. But with their destruction, let us hope the maddened spirits will finally find peace.", objectives = "Slay the insane druids: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26473] = { id = 26473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathran's Hair", description = "There is a plant that grows in the old ruins of Bathran's Haunt across the road to the east. The plant is called Bathran's Hair and is known to cure ailments of the spirit.\n\nNow the Horde are there harvesting the plant for their own evil schemes.\n\nThere is a sick child in Astranaar, and we believe that her illness is more than just physical. I promised my master that I would help seek a cure, but I am no fighter.\n\nWill you go to Bathran's Haunt and gather the plants?", progress = "Have you gathered the Bathran's Hair, {name}?  The child's health grows weaker by the hour....", completion = "Ah, you have the hair! This is a good first step. There are other ingredients that we will need, but the hair of the fallen Ancient could well be the most important.\n\nI only hope that whatever the Forsaken are devising from the plant will not be turned into a weapon. We simply do not have the numbers to remove them right now, especially with Maestra's Post under attack!", objectives = "Collect 8 Bathran's Hair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26474] = { id = 26474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendil's Cure", description = "{name}, now that it has been bathed in Elune's blessed light, I believe that the concoction will help the afflicted child. Please, take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south and then east. However, if you'd like to get there more swiftly, speak with Sentinel Avana.", progress = "I must apologize, for I have no time to speak. My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great! This cure gives me hope, when before I had little....", objectives = "Bring Orendil's Cure to Pelturas Whitemoon at Astranaar in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26475] = { id = 26475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Tear", description = "I'd hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through her. We must find more powerful medicine! Thankfully, Orendil spoke to me of further remedies should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the remains of Iris Lake, destroyed by the eruption of Thunder Peak, northeast of Astranaar. Orendil said the stone will wash away corruption.\n\nPlease, {name}, bring me Elune's Tear and pray it will end my child's sickness!", progress = "{name}, did you find the remains of the lake?  Do you have the Tear?", completion = "Oh, you found it! Odd... it looks tarnished somehow. I will place the tear in a stew, and pray that it will cure her.\n\nThank you! Thank you, {name}!", objectives = "Collect Elune's Tear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26476] = { id = 26476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryad Delivery", description = "Ah, there you are, {name}. I've pored over the notes Teronis has made and it sounds like your next course of action is to find the other pieces of Dartol's rod.\n\nI would start by heading east along the road to Raynewood Tower.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed.\n\nWhat can I help you with?", objectives = "Deliver the Glowing Gem to Shael'dryn at Raynewood Tower in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26477] = { id = 26477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search the Bole", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nTo find the next piece of the rod, you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here near the Felwood border, at the Howling Vale. Once you have it, look for a small glade through the tunnel at the vale. The chest should be hidden around there.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, {name}.", objectives = "Find the Wooden Key and use it to obtain the Iron Shaft portion of Dartol's Rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26478] = { id = 26478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Possum", description = "The last piece of the rod is held by druids of the claw. I asked their leader, Oso Bramblescar, to give it to me, but he and his guardians nearly killed me! Clearly they too were affected by the Horde's corruption of the Forest Heart.\n\nBut, I have an idea for how you can get into Oso's cave and grab the pommel.\n\nEver since I was a faun, I've been pretty good at playing possum. It works great against bears! I can teach you! Go east to the Shady Nook, and if they try to get you, just use my technique.", progress = "Did you find the final piece of the rod, {name}? How did my technique work?", completion = "You got it? Wonderful for you... and for Raene!\n\nI guess we'll have to see about reassembling it, won't we?", objectives = "Obtain the final piece of Dartol's Rod, the Iron Pommel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26479] = { id = 26479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Raene", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nBe careful... I sense a great deal of power within it for both good and ill. I hope that you and Raene know what you are doing.\n\nGood luck, {name}.", progress = "Yes, {name}? How go your efforts?", completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nShael'dryn has been indispensible in her assistance. Teronis would be proud to see his quest is continuing even after his tragic passing.\n\n<Raene looks over the reconstructed rod with a look of approval and thoughts racing behind her eyes.>\n\nNow it is time for us to make use of its power to eliminate the enemies of Ashenvale!", objectives = "Deliver Dartol's Rod to Raene Wolfrunner at Astranaar in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26480] = { id = 26480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartol's Rod", description = "I'm not completely certain what Teronis had in mind next, but if what he said was true about the rod's power, then it will allow you to take on another form altogether, presumably that of a furbolg.\n\nPerhaps he meant to use its powers to get closer to them, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was uncorrupted.\n\nI would start with one known as Krolg. Seek his hut southeast of Mystral Lake.", completion = "Yes, yes... you appear as one of my kind, but I care not what you truly are if you can help the furbolg.\n\nThe night elves and now the orcs have visited many atrocities upon my people.\n\nCorruption runs through our veins, corruption brought down upon us by the prideful night elves and the warlike orcs. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness.", objectives = "Use Dartol's Rod to be able to communicate with Krolg at Krolg's Hut in Ashenvale.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26481] = { id = 26481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Adornment", description = "I'm certain that the long-dead wizard, Dartol, intended to use his rod to subjugate and destroy us just as the night elves and orcs have, but I think now we'll put that thing to an unintended use.\n\nRan Bloodtooth is the king of all of the Ashenvale furbolg. His tribe, the Bloodtooth, are the most powerful and keep themselves secluded in a camp just to the east.\n\nKill them all and bring back his skull. Let us see if we can put it to good use.", progress = "Have you slain Ran yet, my friend? We must have his skull if you're to deliver my people from bondage.", completion = "You have done well, my friend.\n\nNow quickly, hand me Ran's skull. While his essence yet taints it, we shall fashion it upon Dartol's Rod giving you the power to influence my brethren and deliver them from evil!", objectives = "Obtain Ran Bloodtooth's Skull and Dartol's Rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26482] = { id = 26482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Power of the Rod", description = "Now, take the rod and while using its power, speak with my brother, Ota Wen.\n\nOta is amongst the other furbolg that the orcs have captured and have penned in the giant cage on the north side of Silverwind Refuge. The rod will allow you to convince Ota and the other furbolg to rise up and attack the Horde.\n\nThen you may go wherever your path leads you. Just know that you have found a new friend for that which you have done.", progress = "You return, {name}. What's that affixed to the top of the rod? A skull?", completion = "So, you used the skull of the furbolg king to modify the power of Dartol's Rod? You then used that power to convince the captured furbolg to rise up and attack the Horde at Silverwind Refuge?\n\nI am more than pleased and impressed with your abilities, {name}. The Sentinels cannot thank you enough. It should be a simple matter for us to sweep away the orcs and retake the refuge now!\n\nTeronis would be proud. You have my deepest respect.", objectives = "Use Dartol's Rod and speak with Ota Wen. Convince him to rise up against his Horde oppressors. Then, deliver Dartol's Rod to Raene Wolfrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26483] = { id = 26483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'dranda", description = "As fun as it is to butt heads with these trolls, we've got other things to do down here. It'd be nice to get this battle over with, aye?\n\nTheir commander, Gan'dranda, sits in the ruined walls to the southeast of the battlefield. Our boys have most of their forces locked up, so I want you to slip in there and take out Gan'dranda. When they see a {race} standin' over the corpse of their biggest hero it should take some of the fight out of 'em!", completion = "Now that's what I like to hear! Good on ya.", objectives = "Kill Gan'dranda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26484] = { id = 26484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonehearth's Aid", description = "The earthen and the stone troggs somehow found their way to Deepholm through Uldum more than fifteen thousand years ago. They've been warring ever since.\n\nIf we're to recover the middle fragment of the World Pillar, the Stonefather must be rescued.\n\nPlease go to Stonehearth and do everything that you can to aid the Earthen in their war against the stone troggs.\n\nYou're our best hope, {name}.", completion = "The Stonefather's son, Flint, sent you? No time to talk.\n\nWe must prevent a second front from opening up on the war!", objectives = "Speak with Crag Rockcrusher at Stonehearth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26485] = { id = 26485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapjaws, Lad!", description = "I've got plans to brew up somethin' special for those pesky trolls. Aye, I said for them... a brew they won't ever forget! A brew that'll have them pickin' their tusks out of the hillsides!\n\nI've got a few ingredients steepin' already, but I could use a hand gatherin' more. At the bottom of the Overlook Cliffs to the east, near the shore, is a whole mess o' snapjaws. I need fresh, whole gizzards from them for my blastbrew.", progress = "Got those gizzards?", completion = "Ah, nice an' fresh. I'll get those going while you fetch me some more goods then...", objectives = "Collect 8 Snapjaw Gizzards from Saltwater Snapjaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26486] = { id = 26486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "99 Bottles of Booze on the Beach", description = "Now, I know we've got a little battle ragin' and all that, but down at the overlook cliffs are some nice lookin' bottles strewn all over the place. I don't want good drink to fall into the hands o' the Horde!\n\nIf you're down that way, collect the bottles for me and bring 'em back here. I'll pay in full for it as if you bottled 'em yourself.", progress = "About 12 should do the trick, aye?", completion = "That's the stuff! Wouldn't want any trolls or goblins gettin' pleasure out of these, now would we!\n\nMaybe I can work a bit of this into my next brew...", objectives = "Collect 12 bottles of Pupellyverbos Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26487] = { id = 26487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "It's not easy running a combination 5-star exotic resort/jungle resource salvaging plant!  That is, it wouldn't be easy, if I didn't have the organizational skills of a trade prince's personal assistant!\n\nThe first trick is multitasking.  For example: the naga explorers to our south carry a valuable ocean reed - Akiris reeds.  We can sell these reeds to our clients overseas, and we can also stuff our visitors' mattresses with them!  Come to think of it, we could probably use some more of that stuff.", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, you're back already?", completion = "Hey hey!  Not bad, not bad at all!  You may have a future in resource acquisition.  Or hotel management.", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26488] = { id = 26488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Gulp", description = "Arnold and I used to relax down at the moat in the Valley of Heroes.  One day, I lost my locket in the lake and I have never been able to find it.  Rumor has it that huge royal monkfish live in that moat and that they eat anything!  I know it's a long shot, but do you think you could catch a few monkfish and look for my locket?\n\nPlease let me know right away if you find it, it's very precious to me.", progress = "Were you able to find my locket?", completion = "You found it!  I can't believe it was down there all those years!  You have no idea how much this means to me {name}.", objectives = "Fish up a Royal Monkfish from the moat in the Valley of Heroes district of Stormwind. Once you catch a monkfish, fillet it and check if it swallowed the locket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26489] = { id = 26489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's You!!", description = "Yes, can I help...\n\n<Sassy's jaw drops to the floor.>\n\n{name}!  Is it really you?!  Look how big and strong you've gotten!  Let me feel that bicep!\n\nMe?  I've been trying to make my gold here in the jungle.  We're mainly in resource acquisition, but we also do tourism.\n\nI know, genius, right?\n\nHey, listen.  I was thinking... the naga explorers to the south carry Akiris reeds, which we could sell, and use to stuff visitor mattresses.  You interested in killing some naga?  It'll be just like old times!", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, hey Boss {name}.  You're back already?", completion = "I knew you had it in you, boss-man.  You know what they say: You can take the {race} out of the islands, but you can't take the murderous tendencies out of {name}.", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26490] = { id = 26490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime Slime", description = "Not many dwarves know this, but to get a REAL kick out of my brew I add a wee bit of the oozes around here. Aye, the giant green dwarf-eatin' oozes, those ones.\n\nThis brew's gonna have a HUGE kick to it though, so we need a huge slime! There's one lurkin' down in Skulk Rock that's the mother o' them all, absolutely huge...the Direglob, we call it.\n\nIf you've got what it takes, head down there and take a chunk out of the Direglob for me!", progress = "Aye, do ya have it?", completion = "Look at it! That'll put some oomph into the mix!", objectives = "Collect a Direglob Sample from The Direglob.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26491] = { id = 26491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth takin' for our allies!\n\nProblem is, it's full of dwarf-eating slimes and oozes. Those things are slightly less disgustin' than trolls, but they'll still give us a hassle.\n\nWith our boys tied up fightin' the Revantusk, I need you to go to Skulk Rock and clear the place out for me.", completion = "It's good to see you back... and not missing any limbs, either.", objectives = "Kill 10 Jade Oozes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26492] = { id = 26492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Supplies", description = "I had a cousin in the second war! He used to tell me all about when they led a raid on Skulk Rock. Swept in there and drove the trolls out like rats from a nest. They chased right after 'em all the way to Alterac!\n\nThe slimes moved in right quick after that, and there's still cratefuls of old Horde goods sittin' in there. I say we don't let the trolls get it back!\n\nBring me back a few crates from Skulk Rock to the northwest.", progress = "You got the crates?", completion = "Looks like it's still good inside! Huh... is that banana bread? Still fresh!\n\nHere, lad, take your share of goods.", objectives = "Collect 5 Ooze-Coated Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26493] = { id = 26493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Somebody Out There Who Wants It", description = "So, while you're already all sweaty from doing all that other stuff, I was thinking I might grab you for one more task.  You don't mind, do you?\n\nThe latest Science and Explosions journal just came in from Bilgewater Harbor, and there's this article about this hot new reagent.  Prices on the reagent are skyrocketing, and we're in prime position to capitalize!\n\n<Sassy leans over and whispers the details into your ear.>\n\nYou got that?  Good.  You can find the basilisks in a cave, far to the east.", progress = "I hope you used the extraction procedure we discussed.", completion = "Great!  These look... disgusting.  But probably pretty valuable.  Let's get to splitting these up.  Some for me, some for Jasper, some for Chabal...", objectives = "Obtain 7 of Sassy's Secret Ingredient from Thrashtail and Ironjaw Basilisks in the Crystalvein Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26494] = { id = 26494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixmaster Jasper", description = "Mind giving some of this stuff to Jasper, over by the luxury suites?  I'm sure he can find some use for it.\n\nThanks, {name}!", progress = "Hey, is that the stuff?  From the magazine?", completion = "I'll file these away for now.  Maybe we can experiment later.\n\n<Jasper looks over at you.>\n\nYeah, you'll do.", objectives = "Bring Sassy's Samples to Mixmaster Jasper in Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26495] = { id = 26495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chabal", description = "Chabal, that troll over by the botanical gardens/biological weapons lab, is a special guest.  He's a representative of the Zandalari trolls, and has traveled quite far to stay with us.\n\n<Sassy places some of the items you've collected in a small parcel and hands it to you.>\n\nHere, give this to him.  Tell him that the Zandalari are always welcome at Hardwrench Hideaway!  And mention that referrals are key to maintaining our business!", progress = "Care to explain yourself, {class}?", completion = "<The troll looks into the package.>\n\nYou have my thanks.\n\nI have been waiting for you to approach me, {race}.  I have identified you as the most promising {race} here in this strange town.  I have a task for you, if you would be willing to take it.", objectives = "Bring Sassy's Largesse to Chabal in Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26496] = { id = 26496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down with the Vilebranch", description = "The Revantusk isn't the only tribe of foul trolls we're here to take care of! The Vilebranch have corrupted this land for years from their stronghold of Jintha'Alor.\n\nWe're done sittin' by in Aerie Peak twiddlin' our thumbs, if you haven't noticed. Doran Steelwing leads the charge against the Vilebranch from a camp the boys took just to the south. Speak with him and join the fight!", completion = "Well met, {name}! We've got a lot of trolls to kill and only so many hands to do it with!", objectives = "Find Doran Steelwing at Jintha'Alor in The Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26497] = { id = 26497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vilebranch Scum", description = "The Vilebranch are a different tribe from the Revantusk, but the difference is academic. Far as we're concerned the only good troll is a dead troll!\n\nBut make no mistake, the Vilebranch are just as nasty even without the Horde's chain around their neck. They'll poison this whole land unless we take this stand and get rid of them\n\nYou can start with their witchdoctors and headhunters on the lower tier. Let me know when you've killed a fair share of 'em.", completion = "Aye, we'll have these trolls cleared out yet.", objectives = "Kill 5 Vilebranch Witch Doctors and 5 Vilebranch Headhunters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26498] = { id = 26498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Vilebranch", description = "We're makin' good progress. Keep pressing on, and don't falter!\n\nThe Vilebranch berserkers fight like savage animals, whipped into a blood frenzy. Their shadowcasters summon foul spirits from beyond this world! This is why we're getting rid of these depraved creatures, {name}, never forget that.\n\nHead to the middle tier and kill the berserkers and shadowcasters!", completion = "It won't be long until we're the only dwarves left breathing on these walls.", objectives = "Kill 5 Vilebranch Berserkers and 5 Vilebranch Shadowcasters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26499] = { id = 26499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonefather's Boon", description = "With the Stonefather taken prisoner, our forces are demoralized. Normally any one of mine could take five times his number of stone troggs. But now....\n\nI want you to head out into the field surrounding the town. Plant Stonefather Oremantle's banner near my defenders. Grant them his boon and remind them of that for which they fight.", progress = "Rally more of our troops, {name}.", completion = "You have my thanks, {name}. You've made all the difference, and the fate of these cowardly stone trogg ambushers is set in stone.\n\nNow we must get about the business of retaking Stonehearth.", objectives = "Grant the Stonefather's Boon to 12 Earthen Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26500] = { id = 26500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Surrounded", description = "Our war has been waged for longer than your kind counts time. Let us see if you can make a difference, {race}.\n\nThe stone troggs are a mistake of the titans. On your world they have succumbed to the Curse of Flesh. But here, in Deepholm, you see them in their true form.\n\nWe're surrounded. Maybe you could go out there and break a few troggs down for us. See what they're really made of?", progress = "Are you going to pull your fleshy weight, {race}?", completion = "Not a bad start, though you'll have to destroy more of them than that if you're going to rescue the Stonefather.\n\nA lot more.", objectives = "Slay 12 Stone Trogg Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26501] = { id = 26501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Way", description = "The stone troggs have found a way to burrow up from underneath our homes!\n\nI've sent our geomancers to seal all of the buildings, but they need these reagents and enough time out of battle to properly cast their rockslide rituals.\n\nWhen you're done, report to, Gravel Longslab, just to the north on the Fractured Front.", completion = "This is good. We no longer need to worry about stone trogg attacks from the rear.\n\nLet's see what you can do for us on the front.", objectives = "Help the Earthen Geomancers to get out of combat and then give them the Rockslide Reagents so that they can seal the Armory, Inn, Barracks, and Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26502] = { id = 26502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Stones", description = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening.\n\nGo into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults.\n\nWhen you have enough, take them to Clay Mudaxle. Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", progress = "<The older Earthen has cracks where the others do not, clearly ancient.>\n\nWhat are you supposed to be? Some kind of fleshy mistake? Cursed is what you are!\n\n<Clay spits dust.>\n\nMake yourself useful or get off of my front!", completion = "<Clay grumbles to himself.>\n\nThose'll do. Just put them down over there.\n\n<The Earthen looks you up and down with one eye and then spits dust onto the ground.>\n\nI'm going to have something for you to do in a moment. Maybe.", objectives = "Collect 12 Thunder Stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26503] = { id = 26503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Assessing the Threat", description = "Damned worthless gnolls are up to no good. I can feel it in my bones. Gnoll activity in the area has tripled in the past two weeks. I fear they might be mounting up to make an assault on Lakeshire.\n\nI need you to head to each of the gnoll camps of this area and gather any information that you come across. Check the camps directly north of here, east of here and southeast of here. Bring back whatever you find.", progress = "Did you find the gnoll plans?", completion = "I knew it! Looks like Yowler is behind this uprising - which is incredible, because we keep killing gnolls named Yowler. I don't know how many sons the original Yowler had, but it's got to be close to a hundred.\n\nWell, looks like we got ourselves another Yowler to kill.\n\nMagistrate Solomon must be notified.", objectives = "Steal the Gnoll Battle Plans, Gnoll Orders and Gnoll Strategy Guide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26504] = { id = 26504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Redridge Gnolls", description = "By order of the Stormwind Royal Guard, all gnolls of the region known as Three Corners in the southwestern corner of Redridge Mountains, are wanted dead.\n\nShould you dispatch of the gnolls of the region, report your victory to Watch Captain Parker at Tower Watch.", progress = "Come to collect on a bounty?", completion = "A job well done deserves a reward, wouldn't you say?\n\nDon't spend this all in one place, {class}. Better to spread it around, if you catch my drift.", objectives = "Kill any 15 Redridge Gnolls in the Three Corners region of Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26505] = { id = 26505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parker's Report", description = "<Watch Captain Parker hands you a report.>\n\nHere it is, {name}. Take my report to Lakeshire, located north of this tower, and deliver it to Magistrate Solomon. Inform him that we need a more comprehensive solution for dealing with the gnolls. Suggest explosives. Lots of explosives.\n\nAnd stick to the road if you know what's good for you.\n\nWhat's good for you is staying alive, by the way. In case you didn't know what was good for you. You now know... Oh never mind!", progress = "Where did I put my monocle?! Conacher is that you?", completion = "<Magistrate Solomon puts on his monocle.>\n\nOh, you're not Conacher. What have you got there?\n\n<Magistrate Solomon takes Parker's report from you.>\n\nOh for pity's sake. Yowler? AGAIN?", objectives = "Deliver Parker's Report to Magistrate Solomon at Lakeshire in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26506] = { id = 26506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Franks and Beans", description = "I need your help, {race}! Our rations have run out and the guards are getting hungry. They're clamoring for my world famous franks and beans, but I have no ingredients on hand. Would you be a darling and help me out?\n\nI need some goretusk kidneys, condor giblets, and tarantula eyes. You'll find goretusks, condors and tarantulas near this tower. Just look around!", progress = "Have you gotten my ingredients?", completion = "PERFECT! I'll put these in the pot right away. Dinner should be ready in a few hours.\n\nThank you, darling!", objectives = "Collect 4 Tarantula Eyes, 4 Condor Giblets and 4 Goretusk Kidneys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26507] = { id = 26507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petrified Delicacies", description = "Petrified bats.\n\nElementals of that size are picky. You're not likely to find anything better easily.\n\nTo the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory.\n\nI must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", progress = "<Pebble starts to look up at you, eyes glowing faintly, growing rounder and larger every moment.>", completion = "<Pebble leaps upon the pile of petrified bats and rolls around in them, seeming to forget that you exist entirely. Perhaps for the best, if Kor's warnings are to be trusted.>", objectives = "Gather 12 Petrified Stone Bats for Pebble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26508] = { id = 26508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nida's Necklace", description = "My friend Nida lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister {class}... you are very kind!  My kitty thanks you too - isn't that right Effsee?", objectives = "Find Nida's Necklace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26509] = { id = 26509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, {name}, you have done me a great service.  The garden shall be in full bloom this season!", objectives = "Kill Bellygrub and take Bellygrub's Tusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26510] = { id = 26510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Must Prepare!", description = "More of our citizens go missing every day. We think the gnolls are responsible, but we have no idea where they are taking them! If you are to help us defeat the gnolls and find our people, you must be properly equipped. Unfortunately, we are all out of gnomecorders. Without a gnomecorder, there is no way for us to communicate with you when you are in the field.\n\nOur last good gnomecorder was stolen by marauding murlocs last week. You will have to go to Lake Everstill, east of here, and recover it!", progress = "Have you recovered the gnomecorder?", completion = "Excellent! Let me make a few adjustments here and we should be good to go.", objectives = "Recover the Gnomecorder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26511] = { id = 26511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lake Everstill Clean Up", description = "Headed out to Lake Everstill? You'll be happy to know that we currently have a bounty on murlocs. Kill as many as you can and be rewarded! Any murloc will do. All you need to do is kill indiscriminately.\n\nYou'll find Lake Everstill directly east of Lakeshire. It's the lake. Has water in it... Any of this ring a bell?", progress = "Have you killed all the murlocs?", completion = "That ought to teach those murlocs a lesson. Hopefully the next time they decide to raid our town they'll think twice.\n\nWe both know that won't happen.", objectives = "Kill any 10 Murlocs in Lake Everstill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26512] = { id = 26512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuning the Gnomecorder", description = "The gnomecorder looks to be in working order. I've got you all hooked up, now we just need to tune the gnomecorder for reception.\n\nHead north out of Lakeshire and follow the road up to the graveyard. Once you reach the graveyard I'll attempt to transmit.", completion = "<The gnomecorder crackles and pops.>\n\nCan you hear me, {name}? Is this thing on? Ah, yes, I see you there now.\n\nLet's get to work!", objectives = "Go to the Lakeshire Graveyard to tune the Gnomecorder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26513] = { id = 26513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like a Fart in the Wind", description = "We were raided last night, or perhaps it was the night before. I'm not really sure when it was as I haven't had a wink of sleep in three days. I'm probably delusional at this point.\n\nListen, gnolls raided our supply stores and took off with everything! Just like a fart in the wind, they were in and they were OUT! My soldiers saw them running back towards the canyons, northwest of here. Recover our supplies, {class}!", progress = "Did you recover the supplies?", completion = "Thank you, citizen. Without you, we would have starved or worse, been forced to go out and get food for ourselves.", objectives = "Recover 8 Redridge Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26514] = { id = 26514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Romp", description = "<The gnomecorder hums.>\n\nThe first order of business is a romp through the Redridge Canyons, directly north of Lakeshire. Kill every gnome that you see... woops, did I say gnome? I meant gnoll. Kill every GNOLL that you see and take their collars as proof of deed.\n\nI must warn you, {name}; while you are out there, watch out for ettins. My scouts have reported seeing huge, bloodthirsty ettins roaming the canyons lately. Stay out of their way if you want to remain alive.\n\nSolomon out. I'll be in touch.", progress = "Did you recover those collars?", completion = "<The gnomecorder crackles and pops.>\n\nGood work, {name}. I've just been handed some important information. It would appear that our most hated enemy, the Blackrock orcs, have wised up...\n\n\n\nI've transferred a few silver over to you for the gnome, erm, gnoll kills.", objectives = "Collect 10 Redridge Gnoll Collars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26515] = { id = 26515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longo's Revenge", description = "I've got a plan to pit troll against troll.\n\nThe Vilebranch have a big ol' dire troll locked up in a pit with some flimsy-lookin' chains. I've seen those things fight, and there's no way those'll hold if that big brute gets swingin' mad!\n\nI want you to find the dire troll and fight him, {name}. Don't kill him... just smack him around til' he's seein' red, then let him break free and get out of his way! He'll be a big pain for the Vilebranch.", completion = "Ain't that a hoot! Wish I could've seen it myself.", objectives = "Fight Ongo'longo until he breaks free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26516] = { id = 26516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nDon't forget you're not just fighting trolls here, {name}. You're fighting dark and evil forces that'll churn this land into ash if we let them live!\n\nShow no mercy!", completion = "We've cleared straight through 'em! Jintha'Alor is as good as wiped out!", objectives = "Kill 5 Vilebranch Blood Drinkers and 5 Vilebranch Soul Eaters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26517] = { id = 26517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summit of Fate", description = "You have to go to the summit now, {name}. Our warriors won't go past the final gates. They say it's still as a tomb; not a sound, not a breath, not a hint of motion.\n\nThey think it's a trap, but based on what you've brought me, I'm worried it's something even more sinister. Go to the altar, investigate what happened... and bring me back ANY sort of mystical object or dark idol you find! Do you hear me?", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nIt's Shadra. The Spider Loa! They're trying to tap her power!", objectives = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26518] = { id = 26518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heads Up", description = "Umboda Three-Heads is one o' the biggest trolls you'll see around. He's a savage butcher, takin' heads for his own collection, dwarf and troll alike! It's time he got what he deserved.\n\nLook for the big brute on the lower terraces, and you take his own head right back here!", progress = "Let's see it!", completion = "That's one ugly mug. Maybe he was takin' other heads tryin' to find a prettier one!", objectives = "Defeat Umboda Three-Heads and collect his head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26519] = { id = 26519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Who Controls the Ettins", description = "You've stumbled upon a gnoll document. The gnoll that wrote this propaganda is semi-literate:\n\nBROTHERS OF YOWLER, HEAR DIRTPAW! DIRTPAW GIVEN ORB FROM ORCS! DIRTPAW CONTROL ETTIN THINGS! DIRTPAW CRUSH HUMIES! COME GET DIRTPAW PAW-O-GRAPH IN RETHBAN CAVE. CAVE IS WEST, HIDDEN IN CANYON!\n\n<There's a paw print as the signature.>\n\n<There also appears to be a bite taken out of the scroll.>\n\nYou should probably investigate.", progress = "<The orb emanates powerful magic.>", completion = "<The orb hisses as you touch it.>", objectives = "Kill Ardo Dirtpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26520] = { id = 26520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Foreman Oslow", description = "<Upon touching the orb you hear a faint click.>\n\n<You remove the orb from the pedestal.>\n\n<You now control the orb, therefore you now control the ettins. Maybe you can use an ettin to remove the huge boulder currently crushing Foreman Oslow over at Lakeshire. Find an ettin and use the orb on the ettin. Then head over to Lakeshire.>", completion = "You used an ettin to remove the boulder that was crushing Foreman Oslow? Incredible work, {name}! Oslow will be grateful once he regains his composure.", objectives = "Use the Ettin Control Orb to control an Ettin and then use the Ettin Control Orb on your Subdued Canyon Ettin to lift the Huge Boulder off of Foreman Oslow at Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26521] = { id = 26521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. We won't tolerate their foul hexes and dark magic.\n\nIt's time to send a message, and tear down their defenses, all at once! Take this torch, {class}. Set fire to their tiki masks and watch 'em burn. They'll know the Wildhammer want them gone when they see their dark idols consumed!", completion = "The elements dance, and fire consumes. Let the flame show 'em the cost of their wickedness!", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26522] = { id = 26522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, {class}. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26523] = { id = 26523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Skitters", description = "There's somethin' I've noticed up there... Jintha'Alor's full of spiders. Small ones about as big as yer hand. Not an unusual sight for the Hinterlands, but somethin's amiss.\n\nTo be honest, I don't trust the trolls to keep pets. They're up to somethin'. I need you to bring me some of those spiders. Keep 'em alive if you can, and we'll see what the spirits tell me...", progress = "Let's see what you've got.", completion = "By Kurdan's beard... these don't look like any spiders I've seen before. Dark magic's at work here.", objectives = "Collect 8 Skittering Spiderlings in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26524] = { id = 26524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Vessels", description = "The Vilebranch trolls here were always worshippers of the foul god Hakkar, the loa of blood. He was a sick and twisted entity that nearly broke through to our world, but he was defeated long ago.\n\nThe Vilebranch are still stirring their dark cauldrons, ones they filled with blood years before. They're either holding onto hope for a long-dead spirit, or they're up to something new and just as sinister.\n\nGet me those vessels, {name}. We need to examine them with the spiders and see just what's going on here!", progress = "Be careful near those cauldrons, {class}. The Vilebranch won't give them up easily!", completion = "This isn't just blood... it's venom!\n\nSpiders... venom... I hope I'm wrong about my hunches here, {name}.", objectives = "Collect 5 Vessels of Tainted Blood from Jintha'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26525] = { id = 26525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Secrets", description = "If the sacrifice has already been made, Shadra's presence is going to start creepin' into this realm. That cave's probably full of her spawn by now.\n\nDon't let them escape, {name}. Slay any of those vile spiders you find!", completion = "Good riddance. May those horrid things never walk these lands again.", objectives = "Kill 8 Spawn of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26526] = { id = 26526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Keeper", description = "Shadra the spider loa... the venom queen, a spirit of darkness and death! If there's been a sacrifice, they're trying to bring her forth as a last-ditch effort.\n\nIf the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "A tablet! If I can read this... this is a ritual to summon Shadra herself into this world, and a list of the idols needed.\n\nYou've done a good job slaying the keeper and getting ahold of this, {name}.", objectives = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26527] = { id = 26527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon Master Talonaxe", description = "I'd smash this tablet to bits if I had the right, but that's not for me to decide. Gryphonmaster Talonaxe needs to see this.\n\nYou've got to return to Aerie Peak with the tablet. Gryphon Master Talonaxe is in the aviary, tending to the gryphons.\n\nBe swift... and don't let that tablet leave your grasp for a moment!", sourceObjective = "Deliver the Tablet of Shadra to Gryphon Master Talonaxe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26528] = { id = 26528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Shadra", description = "Gryphon Master Talonaxe has sent me here to deal with Shadra, the Venom Queen. The conquest of Jintha'Alor isn't enough... the trolls could regroup and summon this creature later, when we're not expecting it.\n\nWe'll gather the artifacts first, pull Shadra into this world on our own terms, and put our hammers to that foul creature. I'll need you to help find the artifacts, and put a hurt on the rest of the trolls while you're at it.\n\nWe first need the Eye of Shadra, guarded in Agol'watha to the north.", progress = "Was the tablet right? Did you find the eye?", completion = "Well done, {name}. We'll be knockin' on this bug's door in no time.", objectives = "Recover the Eye of Shadra from Agol'watha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26529] = { id = 26529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn. Hideous spiders the size of a dwarf, and twice as strong. Their venom is strong, {name}... don't get careless.", progress = "Have you got the fang?", completion = "There it is... only one left, lad.", objectives = "Collect the Fang of Shadra from the Creeping Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26530] = { id = 26530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shell of Shadra", description = "The final piece is all we need to burn Shadra out for good.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nYou've got to climb that altar to the top and take her out! She'll have the Shell in her possession. Bring it back here.", progress = "Do you have it?", completion = "This is it, lad! We're ready!", objectives = "Kill Qiaga the Keeper and collect the Shell of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26531] = { id = 26531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Shadra", description = "Our best fighters are ready, we've got the idol assembled... it's time, {name}.\n\nHere's what we're gonna do. You'll travel southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples, fighting through the trolls guardin' them.\n\nWhen you do that, Shadra will emerge into our world, and we'll be right there waiting for her with fury in our hearts. Talk to my boys on the scene as soon as you've performed the ritual!", progress = "Are y'ready?", completion = "Talonaxe and the boys are right behind. Let's do this!", objectives = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26532] = { id = 26532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra the Venom Queen", description = "No time to waste, {name}! She's comin' out of the water right now!\n\nGryphon Master Talonaxe is comin' right now with the boys, let's show that bug what for!", completion = "You've done a great thing for the Wildhammer today, {name}. I wish Falstad could've been here for that.\n\nOn behalf of the whole clan, I'd like to repay you for keeping these lands free from that foul shadow. You've earned this reward.", objectives = "Kill Shadra the Venom Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26533] = { id = 26533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI'd like to get my hands on some, {race}.  Check the zombies to the southeast.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Jasper carefully analyzes the strange compound.>\n\nThis mixture is... I don't understand it.  Perhaps we need to run some clinical trials.", objectives = "Obtain 5 vials of Zanzil's Mixture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26534] = { id = 26534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's See What You've Got, Zanzil", description = "Visitors to Hardwrench Hideaway sign a number of waivers upon arrival, one of which allows us to perform basic tests on them.  I'd say it's about time we invoked that clause again.\n\nActually, let's avoid poisoning our customers this time.  Better for business.\n\n<Jasper fills a pitcher with Zanzil's Mixture and some crushed ice.>\n\nThe Hideaway's southeastern tower serves as a temporary jail.  \"Hardwrench Hoosegow,\" we call it.  Anyways, give the prisoners a drink and tell me what happens.", completion = "You don't say!  Well, that certainly is interesting.  In that case...\n\nForget understanding how the stuff works!  I gotta get my hands on that recipe!", objectives = "Offer Jasper's Jungle Cooler to Gmurgl, Orgus, and Captain Bartholomew Softbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26535] = { id = 26535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Disaster", description = "I need Zanzil's recipe, now more than ever.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the other coast of the Cape, and snatch it for me!", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nJust so we're clear, I'm not thinking about using this to make an army of slaves or anything like that.  No, no... I'm much more interested in the ogre explosions!", objectives = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26536] = { id = 26536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Falls", description = "Arnold and I have been fishing in and around Stormwind for years now.  That's the kind of time it takes to find a good fishing spot.  One of my favorites is called Thunder Falls.\n\nIt's just south of Stormwind in Elwynn Forest.  Best part about Thunder Falls is the violet perch.  I have never seen them anywhere else, only up there at the falls.  It's a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?", progress = "Were you able to find the falls?", completion = "These perch look great {name}.  Why don't you join us for a fish fry tonight?", objectives = "Catch 4 Violet Perch from Thunder Falls, south of Stormwind. Return to Catherine Leland with your catch once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26537] = { id = 26537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter Them!", description = "I want you to go out there and I want you to finish them.\n\nBerserkers, Earthrenders, Deathriders... I don't care! I want those stone troggs shattered!", completion = "That's a good dent, but it's clear to me that we're going to have to handle this a slightly different way.", objectives = "Slay any 12 stone troggs on the Fractured Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26538] = { id = 26538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Aid", description = "Many of our warriors didn't survive the Twilight attack on our air fleet. Those that did are swimming to the remains of the fleet, bleeding and badly burned. I need support from the shore to keep my men alive!\n\nThere should be some sort of doctor or medicine man inside of Dragonmaw Port who would be willing to help his fellow orcs out. Go ashore and see if you can bring some medical supplies back to the fleet!", completion = "<Gregor bows respectfully to Zaela.>\n\nIf it is Zaela's wish, then you shall have your supplies. Just don't tell the Dragonmaw Warchief...", objectives = "Seek out a Medicine Man in Dragonmaw Port, somewhere near the shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26539] = { id = 26539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalled Negotiations", description = "The Warchief's whereabouts are unknown! But we have to keep his plan moving forward. {name}, you look like you can get things done.\n\nOur negotiations with the Dragonmaw have stalled. Their Warchief is... not what we expected. I need you to go in there and get negotiations back on track.\n\nMeet with Ornak on the shore, he'll fill you in.\n\nTalk to Horzog on deck here for quick transportation to the shore.", completion = "I'm glad you're here, {class}. Perhaps a seasoned veteran of the Horde's campaigns in Northrend and elsewhere can talk some sense into the Dragonmaw leadership...", objectives = "Speak with Ornak in Dragonmaw Port. Horzog can provide you with quick transportation to the shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26540] = { id = 26540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Compassion", description = "The red dragonflight represents the aspect of life. As such, their blood has healing properties.\n\nThis crate of bandages has been soaked in red dragon blood. It is the last of my supply. May it bring a speedy recovery to your warriors.\n\nWhatever the outcome of your negotiations here, do not forget that you have friends among the Dragonmaw.", progress = "Do you bring any hope for our wounded?", completion = "Dragon's Blood!? We best not tell our red dragon allies that we've used these.\n\nStill, it's powerful magic... We'll have our fighting force back in no time.", objectives = "Bring the Crate of Dragonmaw Bandages back to Warlord Krogg off the coast of Dragonmaw Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26542] = { id = 26542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!", completion = "Welcome to Aerie Peak, {name}. On behalf of High Thane Falstad, I thank ye for comin' to help us.", objectives = "Travel to Aerie Peak in The Hinterlands and speak with Gryphon Master Talonaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26543] = { id = 26543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clammy Hands", description = "Nothing tastes like fresh monstrous clam meat, {name}.  I have been so busy with work these past few weeks that I have not been able to make it out to the local clam spawning grounds.  Think you could run down there and gather some of those tasty treats for me?\n\nThe clams can be found near the shoreline on the eastern coast of Durotar.  Should be plenty right around the Orgrimmar docks.", progress = "Were you able to find the clams?", completion = "Looks like you found the clams, {name}.  These will do nicely.", objectives = "Collect 10 Monstrous Clam Meat from the clams near the eastern shoreline, just south of Orgrimmar. Return to Razgar once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26544] = { id = 26544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They've Wised Up...", description = "<The gnomecorder crackles and pops.>\n\nIt would appear that the Blackrock orcs have finally wised up. I'm getting reports that they're joining forces with the gnolls and planning an attack. I want details, {name}!\n\nI need you to check out Rethban Caverns, located in the western region of Redridge Canyons. Look for orcs with dark skin. Kill any that you encounter and search their corpses for information.\n\nSolomon, out.", progress = "What have you found out?", completion = "<The gnomecorder buzzes and whirs.>\n\nJust put the missive in the little compartment and I'll read it. I am fluent in orcish.\n\n<You hear a distraught yell in the background.>\n\nIt looks like these orcs are here under the direct command of Yowler. That means Yowler must have the orc invasion plan.", objectives = "Recover the Blackrock Orc Missive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26545] = { id = 26545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yowler Must Die!", description = "<The gnomecorder hums.>\n\nYou need to find Yowler, {name}. He'll be located somewhere in the northern region of Redridge Canyons. Kill that mongrel and search his corpse for the Blackrock invasion plans. Should you succeed, bring the plans to me over at the town hall in Lakeshire.\n\nSolomon, out.", progress = "Do you have the Blackrock invasion plans?", completion = "<Magistrate Solomon takes the plans from you and begins reading.>\n\nShadowhide army!? Damn those orcs to hell! These invasion plans speak of a massive build up of orcish and gnoll forces in the east. Looks like Gath'Ilzogg, the Blackrock general, is preparing to march his armies across Lakeshire and attack Stormwind directly!", objectives = "Kill Yowler and recover the Blackrock Invasion Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26546] = { id = 26546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorbeak Friends", description = "Our clan reveres the gryphon as a sacred animal. They're majestic creatures of the skies, and more than just beasts; they're intelligent and cunning.\n\nSome say we keep them, but it's more of a friendship. If you want to befriend the Wildhammer here, first befriend our gryphons! Take this bag o' chow, it's nice and fresh. Our trained razorbeak gryphons wander the forests to the south of the aviary. Go on and feed a few of 'em for me, aye?", completion = "Treat them with respect, and they'll treat you with it as well.\n\nGive 'em guff and you'll be out an eye!", objectives = "Use Gryphon Chow to feed 7 Trained Razorbeak gryphons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26547] = { id = 26547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mangy Threat", description = "We do everything we can to protect our kin and our gryphons. That includes chasin' off predators, whether they be from the forest or from the Horde.\n\nI won't ask you to save us from two-legged monsters just yet. Mangy silvermane prowl the woods to the south where our gryphons range, and they're known to get 'em if they stray too low. Hunt a few of the silvermane and make sure they know our gryphons aren't food.", completion = "Much appreciated, {name}.", objectives = "Kill 8 Mangy Silvermanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26548] = { id = 26548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out to the Front", description = "We need your help with somethin' more pressin', {name}.\n\nThe Horde's been gettin' bolder out here. They've moved in on our territory and started attackin' us outright. The Revantusk forest trolls are attackin' Stormfeather Outpost in broad daylight!\n\nI need you to help out. Talk to Guthrum Thunderfist just outside. He'll put you on a gryphon to Stormfeather Outpost. Kerr Ironsight will fill you in when you get there.", completion = "Good to see you out here! Let's get to it.", objectives = "Speak with Kerr Ironsight at Stormfeather Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26549] = { id = 26549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Madness", description = "Our last two negotiators haven't returned from speaking with the Dragonmaw Warchief. I think we might need to flex a little bit of muscle.\n\nThis time, I want YOU to accompany the negotiator. Their Warchief might think twice once he realizes the Horde is full of battle-hardened heroes like yourself.\n\nSimply escort our negotiator into the main hold in the center of Dragonmaw Port and look menacing.", progress = "{name}, I understand you're going to speak with our \"Warchief\" about joining your Horde.\n\nBe careful, {class}.\n\nSee me afterwards...", completion = "Wake up, {name}! We don't have much time.\n\nI rescued your gear for you.\n\nAt least now you've seen the foolishness of our leader first-hand. His blood is contaminated, his rage is unquenchable -- and he'll destroy us all trying to defeat the Horde!", objectives = "Escort the Horde Negotiator to the main hall in Dragonmaw Port to meet with Warchief Mor'ghor of the Dragonmaw. Speak with Ornak on the coast if you lose your Negotiator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26550] = { id = 26550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the east.  Hir'eek will guide you from there.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution.", objectives = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26551] = { id = 26551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26552] = { id = 26552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Chabal entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26553] = { id = 26553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26554] = { id = 26554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26555] = { id = 26555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours.", objectives = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26556] = { id = 26556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Dumping Allowed", description = "Ever since those goblins took up refuge in Orgrimmar, they have been dumping all of their waste in our water supply.\n\nI have no idea what effect this is having on our local fishing supply, but I don't think it's good.  I have heard reports of a new mutated fish species spawning in that toxic pool near their camp.  A few specimens would really help me figure out what exactly is going on.\n\nCan you help me out?", progress = "Were you able to fish up a few specimens?", completion = "Nice work {name}.  These samples will help us figure out what is going on in that toxic soup over there.", objectives = "Fish up 6 Toxic Puddlefish and return them to Razgar in the Valley of Honor once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26557] = { id = 26557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Staggering Effort", description = "I've fished sandy carp in Orgrimmar's local waters for years now.  Recently, I have noticed my bait is not working as well as it used to.  I suspect it has something to do with all the tauren that moved into the Valley of Wisdom.\n\nI spoke with one of their local fisherman and it just turns out their appetite has changed.  They are biting on stag eyes these days.  You should be able to find plenty of stags north of Orgrimmar, just outside the northern gate.", progress = "Did the eye work as bait?", completion = "Outstanding!  Those sandy carp are picky eaters aren't they?", objectives = "Slaughter a Stag north of Orgrimmar and use its eye as bait to catch a Sandy Carp in the Valley of Wisdom. Return to Razgar in the Valley of Honor once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26558] = { id = 26558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Shadra", description = "The idol is prepared, {name}. I trust that you are as well?\n\nYou will go southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples.\n\nWhen you do that, Shadra will be summoned to this realm. The Deathstalkers and I will be along shortly to subdue and harvest her body. Speak with the lookout I've sent ahead once you've performed the ritual, and await my arrival.", completion = "Marnal draws close... and Shadra even closer. Prepare for bloodshed.", objectives = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26560] = { id = 26560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorgensen", description = "I don't know where Krakauer or Danforth are, but Jorgensen was being held at Render's Camp, northwest of here. I was in the same crap filled cage with him before they relocated me to Alther's Mill.\n\nIf we're gonna get him out we'll need the key. A stone cold witch from hell known as Utroka the Keymistress holds on tight to that thing. We'll have to kill her if we're going to get Jorgensen's cage key. She's up north in the valley leading to the Burning Steppes.\n\nLet's go, kid.", progress = "Messner! Damn, it's good to see a friendly face. Get me out of here!", completion = "I know where they're holding Krakauer and Danforth. We gotta hurry. They were prepping those two for a sacrifice!", objectives = "Retrieve Jorgensen's Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26561] = { id = 26561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krakauer", description = "Krakauer is up on the chopping block as we speak! The orcs brought in a Gurubashi witch doctor to perform a dark ritual on him. We need to kill that troll to free Krakauer!\n\nLet's go! He's just inside the cave here. Hang a right at the first fork.", progress = "<Krakauer groans.>", completion = "Wha... Where am I? What happened? Messner? Jorgensen?\n\nOH MY GOSH! We have to get to Danforth! It might already be too late!", objectives = "Kill Ritualist Tarak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26562] = { id = 26562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Last But Not Least... Danforth", description = "Danforth's being tortured on the other side of the cave. There's no telling what state he's in by now! We need to get over there and save him!\n\nOverlord Barbarius has the key to the lever holding Danforth up. We work together as a team and we can kill that bastard, Barbarius. Once Barbarius is dead, we use his key to get Danforth down and get out of here!\n\nReady?", progress = "Well look at that! The team's all here... everyone but Keeshan.", completion = "About damn time you sissies showed up. My arms were gettin' tired.", objectives = "Kill Overlord Barbarius and recover the Blackrock Lever Key. Use the Blackrock Lever Key to free Danforth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26563] = { id = 26563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Bravo Company", description = "I don't know who you are, <mister/missy>, but you've earned the respect and admiration of the Bravo Company. You've managed to save all our hides and kill a boatload of orcs in the process. Now we return the favor.\n\nGet back to Lakeshire and report to Colonel Troteman. We'll find Johnny and deliver the good news in person. With the Bravo Company back in action, these orcs don't stand a chance.", completion = "<Colonel Troteman salutes.>\n\nUnbelievable work, {name}. You've managed to rescue the entire Bravo Company from the clutches of the Blackrock orcs? With Keeshan's team rescued and Keeshan's belongings returned, there's no way Keeshan could refuse us.", objectives = "Report to Colonel Troteman at Lakeshire in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26564] = { id = 26564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fixer Upper", description = "<Clay sneers at you and makes a sound much like two stones rubbing against each other.>\n\nThey've smashed all of our catapults. I've been trying to get this one working, but no luck so far.\n\nMaybe you'd like to make yourself useful. Head out onto the front and grab me any spare parts you come across.\n\nYou think you can handle that, flesh bag?", progress = "Well? I don't have all day.", completion = "Well then. Maybe you're okay after all.\n\nAlright, alright... don't get all bent out of shape. Just give me a few moments with these parts.", objectives = "Collect 6 Catapult Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26565] = { id = 26565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Furious Catch (REMOVED)", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The southfury river flows just west of Orgrimmar and your challenge can be found within it's mighty flow.\n\nWe are looking for a furious pike.  This mighty fish used to be prevalent in these areas but ever since the floods hit, they have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", objectives = "Catch a Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26566] = { id = 26566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Triumph of Gnomish Ingenuity", description = "We will need all the weapons, inventions, and soldiers we can get in order to defeat Razlo Crushcog and his followers.\n\nOver to the northeast, you'll find Engineer Grindspark, one of a new generation of brilliant gnomish minds. Why, he hasn't had an explosion in over three prototypes!\n\nBut enough bragging. Engineer Grindspark is working on a bot that he says will help clean up the toxic airfield. You should introduce yourself to him and see if he needs any help testing it.", completion = "So the high tinker himself has heard of my little project? Splendid! I've almost finished my latest prototype, but maybe you can help me chase down those last few parts.", objectives = "Speak with Engineer Grindspark in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26567] = { id = 26567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "John J. Keeshan", description = "You ever heard of John Keeshan, {name}? I was his commanding officer throughout all three great wars. Let me tell you, that man has killed more orcs than any man alive. If anyone can stop the Blackrock orc invasion, it's JOHN J. KEESHAN. We need to get him to help us or Lakeshire will be nothing more than a mound of rubble and ash after that massive Blackrock army marches through to Elwynn.\n\nI heard he was fighting in the underground fight club at the Lakeshire inn. Find him and tell him everything you know.", completion = "Help you? Help these people? These people that would rather spit on me than crack a smile?", objectives = "Enlist the help of John J. Keeshan at the Lakeshire Inn in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26568] = { id = 26568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Ain't My War", description = "They asked me to fight in those wars. I didn't ask them! I did what I had to do to win. So I end up getting captured by those filthy, crap-swilling, maggot orcs and for five long years they used me as a toilet. Finally I break out and head back to my hometown and what do I get? People spitting on me, protesting me, calling me a baby orc killer and all kinds of vile crap!\n\nNo, I don't think I'll be helping you. You go back to Troteman and you tell him that this ain't my war.", completion = "<Troteman sighs.>\n\nI'm not giving up on him, {name}, and I'm not giving up on Redridge. We need to boost his spirits... Rouse the slumbering monster within him!", objectives = "Return to Colonel Troteman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26569] = { id = 26569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying Equipment", description = "Ah, my savior! I've heard that you're on a mission to save Lakeshire... and my bridge. Yep, worked too damned long on that thing to let it get destroyed by an army of marauding orc monsters!\n\nListen, if you're headed up north towards Render's Camp, would you do me a solid and get me some spyglasses from the Blackrock trackers up there? I could sure use 'em for my new surveying gear.", progress = "Did you recover the spyglasses?", completion = "Fantastic work, {name}! These will come in handy for our next project, the Lakeshire SUPER BRIDGE, meant to traverse the length of Lake Everstill. It should be done in 20 or so years. Give or take a decade or two.", objectives = "Recover 5 Blackrock Spyglasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26570] = { id = 26570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Render's Army", description = "Heading up north, eh? How about you wage your own little war against those Blackrock monsters? What do you say, {name}?\n\nKill any Blackrock orc that you see at Alther's Mill or Render's Camp. Kill until your skin turns red from their blood splatter and then come back to me and I'll pay you handsomely.\n\nIt might not stop the Blackrock invasion, but it'll be sure to put a kink in their plans.", completion = "You've probably bought us another day, maybe two. Nice work, {name}.", objectives = "Kill any 25 Blackrock Orcs in Alther's Mill or Render's Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26571] = { id = 26571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of War", description = "What I'm about to ask of you isn't going to be easy to accomplish, {name}. Keeshan left everything back there in that orc prison, and I'm not just talking about his soul or his will to live.\n\nIf we're going to get Johnny ready for war, we need to recover his prized possessions. The orcs now hold Keeshan's bow and his survival knife.\n\nHead to Alther's Mill, east of here and look for two orc lieutenants, Murdunk and Homurk. They've got Keeshan's gear. Get it back.\n\nI'll be in touch via gnomecorder.", progress = "Did you terminate Murdunk and Homurk?", completion = "<The gnomecorder buzzes with energy.>\n\nCome in, {name}. Do you copy? Troteman here! Great job on getting Keeshan's weapons back! Now there's one final mission you have to run. Are you up to the challenge?", objectives = "Recover Keeshan's Bow and Keeshan's Survival Knife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26572] = { id = 26572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Opportunity", description = "You heard of the golden stonefish, {name}?  The thing with these fish is that they can't be caught by normal means.  They have jaws so strong that they snap right through any hooks or lures you try to use on 'em.\n\nYou can find a number of them in Thunder Ridge, south of Orgrimmar.  That ridge used to be full of thunder lizards, but they all drowned in the flood.\n\nTake my knife, swim down there and cut off their tails.  You should be able to use the tail to zap any stonefish you find.", progress = "How did it go down there?  Any luck with the tails and the stonefish?", completion = "Nice one, {name}!  I tell ya, golden stonefish are not easy to come by so this is a nice treat.", objectives = "Use Razgar's Fillet Knife to cut off a Drowned Thunder lizard Tail in Thunder Ridge, south of Orgrimmar. Once you have the tail, use it near a Golden Stonefish to kill it. Return to Razgar in the Valley of Honor once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26573] = { id = 26573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Heart Must Be In It", description = "<The gnomecorder clicks.>\n\nHis gear alone won't be enough, {name}. His heart must also be in this battle. To capture that, we need items of sentimental value. The Blackrock orcs of Render's Camp, located in the north, hold two such items that belong to Keeshan.\n\nGet up there and search their coffers for Keeshan's headband and a jade amulet left to him by his wife - who was brutally killed during a Blackrock orc invasion.\n\nBring them back to me should you succeed.", progress = "Did you locate the headband and amulet?", completion = "I hope with these items and with his crew all rescued he'll have a change of heart. We can't do this without Keeshan.", objectives = "Recover Keeshan's Red Headband and Keeshan's Jade Amulet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26574] = { id = 26574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adella's Covert Camp", description = "Lady Shandris has already asked for you to assist us further.\n\nAdella has struck out to the east, among the woodpaw gnolls, and established a foothold south of Camp Mojache. You are to report to her if you wish to assist Lady Shandris and the Alliance further.\n\nDon't stray too close to Camp Mojache... the Horde will not hesitate to attack. Keep to the south and look for our banners.", completion = "Welcome to Shadebough, {name}. Lady Shandris sent word of you.", objectives = "Report to Adella at Shadebough in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26575] = { id = 26575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Bottom", description = "I've one more favor to ask, fleshling.\n\nThere is a basilisk, much larger and much older than the rest. Though we normally fear nothing from their kind, this one has become so potent as to petrify some of my sons. This shall not be abided.\n\nFind Gorgonite to the east and slay him. He has lived much longer than necessary.", completion = "Thank you, {race}. You've done all that I can ask of you. I shall impart my favor for you to the Stonemother.\n\nMay the stone beneath your feet hold you steady during your quest for the World Pillar.", objectives = "Kill Gorgonite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26576] = { id = 26576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Hand", description = "Nearby to the north, you will find Terrath the Steady. He has taken upon the task of pulling the stone dragons back into the fold. We find ourselves repeating this trial every few hundred years... the stone dragons are fickle, and bend only to strength.\n\nTerrath is balanced and reasonable, but his goals may not be easily accomplished. Go to him. Appeal to the more balanced side of the Stonemother.", completion = "Greetings, {race}. I have been told of your coming. If you wish to aid me, then perhaps I can be of aid to you as well.", objectives = "Speak to Terrath the Steady at the Pale Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26577] = { id = 26577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocky Upheaval", description = "To the east, on the Crimson Expanse, you will find Gorsik. He embodies the more unstable and violent nature of our kind. He is neither friendly, nor trusting, but his word carries weight.\n\nProving yourself to Gorsik will go a long way towards proving yourself to the Stonemother.", completion = "You are Diamant's chosen.\n\nSo small. So fragile.\n\nDo you realize that your actions shall be the basis by which your entire, \"Earthen Ring\" is judged? You truly think you can stand for so many?\n\nYou are a fool. A confident fool. We shall see if you are a capable fool as well.", objectives = "Speak to Gorsik the Tumultuous upon the Crimson Expanse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26578] = { id = 26578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomshrooms", description = "The rift to your world has poisoned our home. Corrupted it. Polluted it.\n\nThis expanse festers and grows. It becomes difficult to even see the purity of the rock beneath this filth.\n\nIf you are here to lend your aid, then go about cleansing this overgrowth. Look for the brightly glowing mushrooms that are growing faster than the others. They are the worst of the offenders.", completion = "You have appealed to Diamant. He is patient. Trusting. Perhaps too much so. You have much to prove if you wish my favor, {race}.\n\nStill, this is a start.", objectives = "Destroy 10 Doomshrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26579] = { id = 26579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gone Soft", description = "The fungal behemoths that surround us have succumbed to a weakness very similar to that that affects your kind. Their skin has grown soft. They no longer belong with the stone.\n\nKill them. We do not wish to see this infection spread.", completion = "You carry with you a certain degree of potency. I can find some respect for such strength, especially in your kind.\n\nMy concerns are not yet abated. Not for the source of the overgrowth, and not for you.", objectives = "Kill 8 Fungal Behemoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26580] = { id = 26580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Intruders", description = "Fleshling. Some of your kind skitter among the rocks. Too cowardly to approach, too swift to be crushed.\n\nIf you wish my favor, deal with them. I tire of these games.", completion = "It is good to see you again, brother. I see that your efforts go well. The Stone Lords appear to be showing you some degree of trust.\n\nWe've come to help. We might be of some aid in tracking down the source of this sudden growth. I highly suspect your giant friend's aggressions are focused in the wrong direction.", objectives = "Speak to the \"fleshling\" intruders in the Crimson Expanse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26581] = { id = 26581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Head Full of Wind", description = "I'm no druid, but some of these mushrooms do not look to be naturally occurring. I know that our Stone Lord friend over there is eager to blame this on exposure to Azeroth, but I suspect more domestic causes.\n\nI saw some clouds of red mist to the northeast, near the water's edge. They seemed to be spurring new growth in their wake. Take one of my wind-devils with you and get me a sample from those clouds. You may have to stay close to the ground to spot them.", completion = "You let the mist touch your skin? I hope there weren't any adverse affects.", objectives = "Bring Lorvarius' wind-devil to the clouds of red mist in the Crimson Expanse, near the water, and then return with a sample.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26582] = { id = 26582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatural Causes", description = "This is most definitely magic in origin. Not even druidic. I suspect one among the stone troggs to the north.\n\nGo to Gorsik and point him in their direction. Hopefully this will help earn his favor.", completion = "The stone troggs? And I am to trust you at your word?\n\nI have no love for the Verlok anyway. Suspicion is more than enough reason to lay waste to them. We shall see if your word is true.", objectives = "Speak to Gorsik the Tumultuous in the Crimson Expanse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26583] = { id = 26583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Fungalmancer", description = "Their leader hides within his hole ahead. He is the one that has brought the plague upon the crimson expanse.\n\nHe must be killed.\n\nOne of your Earthen Ring companions is already inside. You should speak with her.", progress = "I cannot fit inside. Our elementals are not up to the task.\n\nYou must see this done.", completion = "Well done, {race}.\n\nGorsik shall hear of your deed. Therazane shall hear of your deed.\n\nYou are quite vicious for one so small... and so soft.", objectives = "Speak to Earthmender Norsala, then kill Fungalmancer Glop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26584] = { id = 26584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaken and Stirred", description = "I have sent my brothers to assault the Verlok village from below. The Verlok will gather on their rocky ledges, as they always do to avoid our ire. When they do, we shall make the earth itself shake them until they fall at our feet below.\n\nThat is where you prove your use. When they fall to the ground amongst my brothers, make sure that they do not rise again.", completion = "Well done fleshling. Your presence complimented my brothers well.", objectives = "Kill 8 Verlok Pillartumblers in the lower section of Verlok Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26585] = { id = 26585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption Destruction", description = "If this disgusting growth is truly brought on by the Verlok, then their supplies will be in their village to the north. Bring them to me so that I can verify your claims.", progress = "I await your proof, {race}...", completion = "So your words prove true. You have my gratitude, {race}.", objectives = "Retrieve 8 bags of Verlok Miracle-Grow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26586] = { id = 26586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bravo Company", description = "If you and Keeshan are going to defend Lakeshire, we're going to need to find his old battalion. Last I heard all of 'em - Messner, Jorgensen, Krakauer and Danforth - were captured by the Blackrock orcs. Now I don't know where they could possibly be or if they're even alive, but I'd be a damned fool if I didn't ask you to try and find 'em.\n\nSearch Alther's Mill, east of here, for any clues.", completion = "Keeshan? You mean JOHNNY'S ALIVE? You bet your sweet behind I'll help, but first you gotta get me out of this damned cage.", objectives = "Search Alther's Mill for a member of the Bravo Company.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26587] = { id = 26587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Out is Hard to Do", description = "The key to this cage is stored in a pouch over at the worg den, just north of our location. The problem is that the pouch is resting safely atop a tree stump amidst a sea of bloodthirsty man-killing worgs.\n\nYou've got one shot to get that key without waking up any of those sleeping worgs. Head to the worg den and find a way into the center. Tread carefully and watch out for the Blackrock worg captain. Get the key and return to me.\n\nIf you got a pet, I'd recommend telling it to stay back!", progress = "Did you get the cage key?", completion = "IT'S PAYBACK TIME!", objectives = "Retrieve Messner's Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26588] = { id = 26588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Furious Catch", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The Southfury River flows just west of Orgrimmar and your challenge can be found within its mighty flow.\n\nWe are looking for a giant furious pike.  This esteemed fish used to be prevalent in these areas but ever since the floods hit, the big ones have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", progress = "Were you able to catch a giant pike?", completion = "{name}, you got one!  It's a rare day that I get to see such a strong, beautiful fish.", objectives = "Catch a Giant Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26589] = { id = 26589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Konu Runetotem. He has found signs of a disturbing illness.\n\nFollow the road west around the Twin Colossals to find Camp Ataya. Go in peace, {name}, and walk with the Earth Mother.", completion = "Peace, friend. I wish we could have met under less troubling circumstances.", objectives = "Travel to Feralas and speak with Konu Runetotem at Camp Ataya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26590] = { id = 26590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Holy Water of Clarity", description = "Hey, listen.  You don't look like any old tourist, and I'm in a bit of a pickle.  My cousin up north sent me this weird artifact, and I need your help to... ah... identify it.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  Rumor has it that whoever drinks from this spring is given a vision of clarity.\n\nSounds pretty promising, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... that artifact.  Clarity...\n\nI've got it!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26591] = { id = 26591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefront Triage", description = "You seem quick on your feet, {race}. I need someone to go out into the chaos of the front and patch up our injured.\n\nTake my kit. It's simple enough to use.\n\nHeal them before the stone troggs finish them off for good.", completion = "If you ever get tired of your being a {class}, come look me up. You seem very good with those fleshy hands of yours.", objectives = "Patch up 10 Injured Earthen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26592] = { id = 26592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diffractory Chromascope", description = "To properly identify this artifact, I will need tools for analysis.  A diffractory chromascope should suffice, I think.\n\nI already have the mithril casing, which surprisingly, is the hardest part to find.  We simply need two other pieces: a ruby and a sapphire.\n\nThere's pirates nearby, just to our south, and a bit farther to the east.  Pirates love treasure... why don't you see if you can find some gems for me?", progress = "<Flem's eyes sparkle.>\n\nAre those gems I see?", completion = "<Flem weighs the gems in his hands and nods in approval.>\n\nYes, these will do.  Now to perform the analysis...\n\n<The goblin clacks the gems together for a while, then looks up at you.>\n\nOh, you're still here?  You don't think I'm a fraud or something, do you?", objectives = "Obtain a Bloodsail Ruby and a Bloodsail Sapphire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26593] = { id = 26593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me.  Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt elder mistvale gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?", objectives = "Obtain 5 Mistvale Giblets from Elder Mistvale Gorillas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26594] = { id = 26594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", progress = "Here here, {name}.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, {name}.  Now it's your turn to get paid...", objectives = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26595] = { id = 26595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill-Collect", description = "There's three phases to debt collecting: asking nicely, asking forcefully, and something I like to call \"Phase Three\".\n\nUnfortunately, collecting during Phase Three is something that this old dog can't do any more.  That's why I employ so many cronies, stooges, mooks, goons, and noble adventurers like yourself!\n\nJuntz Fitztittle, Ephram Moonfall, and Maury Wilkins are hiding out on the eastern coast.  You should have no problem visiting them all in one trip... and bringing back their valuables.", progress = "{name}, did you find those debtors?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, {name}!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with.", objectives = "Obtain Maury's Clubbed Foot, Fitztittle's Ratcheting Torque Wrench, and Ephram's Jeweled Mirror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26596] = { id = 26596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Kalimdor", description = "I've been sent by the good people of Theramore to find loyal members of the Alliance who are willing to help Lady Jaina with some problems in Dustwallow.\n\nYou weren't really here working for the goblins, were you?\n\nThe path back to Dustwallow will take you through Ratchet.  Wait on the end of this pier for the next boat.  Once you get to Ratchet, speak with Gazlowe.  He'll point you in the right direction from there.\n\nUgh, I think I stepped on a fish!  And it flopped!", completion = "Yeah?  Whaddya need?", objectives = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26597] = { id = 26597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick... have contracted Stranglethorn Fever....\n\n...technically... CAPE of Stranglethorn Fever....\n\n...deadly v-v-virus....\n\n...only cure... is... is... to eat the heart of M-m-m-m-mokk the Savage... elusive white beast....\n\n...Witch Doctor Unbagwa... only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape....\n\n...hurry... dying... dying....", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might I be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me....", objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26598] = { id = 26598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Mokk", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!" }
quests[26599] = { id = 26599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  I will not rest until their corpses pepper the ocean floor!\n\nOne of the giants, Gorlash, stole my captain's chest.  I hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", progress = "Ahoy, {name}!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  What a glorious day for ol' Hecklebury, this is.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete...", objectives = "Obtain Smotts' Chest from Gorlash in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26600] = { id = 26600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Giant's Feast", description = "The next giant on my list is called Negolash.  I remember vividly how he leapt from the seafoam and plucked poor Poop-Deck Paul from the crow's nest.\n\nSwallowed him in one gulp, he did.  And snapped my mizzenmast in two on the way down.\n\nNo man on my crew deserves such a heinous death.  So we're going to use Negolash's appetite against him.  Kelsey Yance should be able to sell you some meat, and Whiskey Slim has enough booze to knock out... well, a sea giant.  You'll find both of them in town.", progress = "We're going to need a lot of food, {name}.  Quantity over quality is the goal here.", completion = "This wasn't expensive, was it?  Well, here's some pieces of eight to reimburse you.\n\nNow let's get onto this revenge, shall we?", objectives = "Purchase a Crate of Grade-E Meat from Kelsey Yance and a Crate of Pupellyverbos Port from Whiskey Slim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26601] = { id = 26601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'rash the Cleaver", description = "Mok'rash the Cleaver is the last of the lot.  And the largest, by my memory.  Taller than a wave in a windstorm, with a beard like a kelp forest and a hammer like an oak tree.\n\nHe taunts me from Janeiro's Point, the island right off the end of this very pier.  It's because of him that I'm still trapped here, living this lamentable landlubber's life.\n\nIf you can swim, then head out to Janeiro's Point and slay Mok'rash.\n\nTake care, {name}.  Mok'rash will not lay down as easily as his brothers.", progress = "I've been waiting for this moment, {name}.", completion = "Mok'rash... Negolash... Gorlash... they're all gone.\n\nI suppose I have no excuses now.  I can return to the high seas and a life of pillage and booty!  And it's all thanks to you.\n\nNow I just need to get myself a ship...", objectives = "Kill Mok'rash the Cleaver at Janeiro's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26602] = { id = 26602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish Best Served Huge", description = "Take this food, and put it in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come running!\n\nAnd when he does, there will be a stouthearted {class} ready to knock his corpse back into the briny deep.", progress = "Is it done, {race}?", completion = "I can't believe my fortune, {name}!  Meeting you has turned my luck to the better, make no mistake there!\n\nIf I ever get a new ship and you're looking to sail the seas, you would be my honored guest.", objectives = "Bring the Giant Crate of Giant Food to Captain Smotts' lifeboat, then use it to summon and kill Negolash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26603] = { id = 26603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message in a Bottle", description = "Inside the bottle you find a note which reads, in fairly good handwriting:\n\n<To any that can aid me->\n\n<Please, my need for help is dire. A great beast holds me captive on an island in the South Seas.>\n\n<The stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see shoreline to the northwest, and what seem to be large sailing ships to the southwest.>\n\n<I beg of you, my would-be savior, please help me.>", completion = "Have you come to free me?", objectives = "Find the author of the message at Jaguero Isle in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26604] = { id = 26604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Her Royal Highness Poobah", description = "These vicious jungle cats have been circling me for some time now.  I watch them as closely as I can, but they seem to just... disappear into the grass.\n\nHow they snarl and hiss!\n\nDon't get me wrong... I still want you to rescue me, but first, clear out some of these cats.  I won't need to be rescued if I end up someone's dinner.", progress = "Please, my hero, dispose of the stalking panthers!", completion = "It's about time you returned.  I was beginning to worry that I was going to be eaten while you hunted.\n\nA cat eating a princess... wouldn't that be a fancy feast?", objectives = "Slay 5 Jaguero Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26605] = { id = 26605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubby Little Paws", description = "I understand that you're anxious to rescue me, but the time is not yet right.  First I'm going to need some of my things.\n\nThe gorillas and the monkeys on the other side of the island have taken most of my possessions.  I'll need my tiara, my scepter, my slippers, and my diary before I'm ready to leave.\n\nWhat?  Stop looking at me like I'm some sort of insane person.  You don't know what it's like being a princess.", progress = "I shudder to think what Mukla plans to do with me.", completion = "<Poobah surveys her belongings.>\n\nLooks like it's all here.  Alright, I think I'm ready to be rescued now.", objectives = "Obtain Poobah's Tiara, Poobah's Scepter, Poobah's Slippers, and Poobah's Diary from the apes on Jaguero Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26606] = { id = 26606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mukla's Demise", description = "{name}, I now put my faith in you to help free me.  The great Skymane King Mukla is my captor.  He commands the beasts of this island, and they keep me here against my will with the aid of this chain.  If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "{name}, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.", objectives = "Slay King Mukla obtain the Shackle Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26607] = { id = 26607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Drew First Blood", description = "Take this bundle of Keeshan's possessions and head back to the Lakeshire inn basement. Bravo Company is already there, talking to Keeshan. Remind him of who drew first blood, {name}. Lakeshire needs Keeshan. The Alliance needs Keeshan.\n\nDismissed, soldier!", progress = "You again?", completion = "<Keeshan takes the bundle from you and opens it.>\n\nMy bow... and knife! Where did you...\n\nJade's amulet... My darling Jade.\n\n<Keeshan picks up his red headband.>\n\nWe got orcs to kill.", objectives = "Deliver Keeshan's Possessions to John J. Keeshan at the Lakeshire Inn in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26608] = { id = 26608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations Terminated", description = "Go now, go back to your fleet. Tell them what kind of a monster claims authority over the Dragonmaw.\n\nOur \"Warchief\" is a traitor to his blood. Since his return from Outland he reeks of demon and leads what remains of our clan to ruin.\n\nHelp rid the Dragonmaw of Mor'ghor, and those of us with pure blood will be your allies forever. This I can promise.", completion = "The Fel Orcs from Outland have laid claim to the Dragonmaw? Obscene!\n\nIf Hellscream knew what was happening here, he'd raze their city to the ground...", objectives = "Return to Admiral Stonefist off the shore of Dragonmaw Hold in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26609] = { id = 26609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving {race} {class} is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nWe've made Booty Bay our happy home away from the high seas, but word has it that the Bloodsail have some new plan cooked up.  All me boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", completion = "On top of the barrel, you discover a map with some hastily written text on it, along with some coins.", objectives = "First Mate Crazz wants you to check the cove north of Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26610] = { id = 26610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodsail Treachery", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"Set up your command post here, and bide your time.  The Fleet Master will send out word when it's time to make your move.\"\n\n\"I'm placing Lieutenant Bruce in charge here.  This time will be different.  This time we take Booty Bay once and for all.\"\n\nThe map is held in place with a dagger, placed right through the location of Booty Bay.", completion = "Sure, I remember you, {class}.  Back from scouting I see....", objectives = "Report your findings to First Mate Crazz in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26611] = { id = 26611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baron Must Be Told", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Baron Revilgaz at once!  You'll find him here in Booty Bay.", completion = "Bloodsail Buccaneers attacking Booty Bay?  This isn't the first time that those blaggards have tried something.  Booty Bay is impenetrable!\n\nSounds like they might be changing their strategies up, though.  Wouldn't put it past Firallon to try something crazy.  Very well, let's see what else they're up to.", objectives = "Report the planned Bloodsail attack to Baron Revilgaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26612] = { id = 26612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Details of the Attack", description = "I want to know details, {name}.  Our supremacy over the Bloodsail is due largely in part to our stronghold here in Booty Bay, but intelligence also plays a critical role.\n\nThe Bloodsail maintain a few meager camps to the south which they call their \"Southern Command.\"  Well, you're going to raid their excuse for a southern command, find their plans, and slaughter their men.  Return with whatever information you can find.", progress = "Ahoy, {name}.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, {name}.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape....", objectives = "Kill 8 Bloodsail Sea Dogs and 8 Bloodsail Elder Magi, and bring back the Bloodsail Charts and the Bloodsail Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26613] = { id = 26613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless {class} like you could convince 'em to share the goods, eh?", progress = "Any luck finding the goods, matey?", completion = "Good show, {name}!  And just before I need to ship out too!  Can't thank you enough, old friend.", objectives = "Deeg in Booty Bay wants you to bring him 15 tiny heaps of Snuff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26614] = { id = 26614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n<Kshhh-thunk>\n\n{name} ho!  Blimey, I can see!!", objectives = "Retrieve Dizzy's Eye from the Bloodsail Buccaneers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26616] = { id = 26616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Never Over", description = "Those Blackrock orcs are gonna need an army to handle the Bravo Company and you, {name}. When you're ready to go, meet us at the dock facing Lake Everstill and we'll set off on my riverboat for Camp Everstill on the other side of the lake.\n\nSee you there, {name}.", completion = "It's orc killin' time.", objectives = "Take Keeshan's Riverboat to Camp Everstill in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26617] = { id = 26617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Sea Dog", description = "This old, weathered coin was found on the body of the pirate \"Good-Boy\" Bruce.  Its front side bears the image of a large, unfamiliar pirate ship; on its back side, the term \"Brashtide Crew\".\n\nSomeone who has been in the piracy business for some time might know what this coin is, or what it means.", progress = "What's that you've got there, {race}?  Let me see it.", completion = "That coin!  Where did you get it?\n\nBruce... yes, I see.  He was one of the Blackwater Raiders once.  One of us, before Greymane closed the Gilneas ports and held his crew captive.\n\nI know that what happened in Gilneas changed the people there, but I never expected them to change their loyalties.  Especially not Bruce.\n\nIf you wouldn't mind, could I keep the coin?  I'll pay its worth in gold.", objectives = "Bring the Weather-Beaten Coin to Fleet Master Seahorn in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26618] = { id = 26618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves at Our Heels", description = "The dire wolves are the most common threat to the townsfolk here. They lurk in the forests on all sides of us, though most are along the north bank of the river.\n\nThese aren't the runt dogs you see in Elwynn, or wherever you come from. They're big as a man and twice as vicious.\n\nIf you wish to assist the people of Darkshire, hunt the dire wolves so our streets can be safer.", completion = "Don't go thinking that was too easy. Far greater dangers lurk deeper in the woods.", objectives = "Kill 12 Dire Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26619] = { id = 26619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Say You Want a Revolution", description = "If what you say is true, {name}, then we have friends within the Dragonmaw Clan. We can support an insurgency from within their ranks and avoid a lot of bloodshed on both sides.\n\nI can help, but the most dangerous part is up to you.\n\nMy Axebite Warriors will launch an offensive on the shores. During the confusion, I need you to slip behind the lines and speak with your revolutionary contact, Zaela.\n\nWe'll arm the Dragonmaw and overthrow their fel masters!", completion = "{name}, what are your people doing? Are you attacking the Dragonmaw or are you here to rid us of Mor'ghor's corruption?\n\n\n\nAh, I see now. I like the way you think. Warchief Mor'ghor won't even know what hit him.\n\nLet's do this!", objectives = "Slip through the front lines at Dragonmaw Port and speak with Zaela.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26620] = { id = 26620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasoned Wolf Kabobs", description = "Seasoned wolf kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.\n\nBring me five wolf skirt steaks.  The dire wolves near the river north of town are good to hunt; I wouldn't stray too far into the woods if I were you.", progress = "Were you able to find five wolf skirt steaks yet?", completion = "Mmm-mmm! The skirtsteak's the best part. It's not an efficient way to cook, though.\n\nHere, have this recipe. It's a little different, but flank meat's easier to come by when you really need a meal.", objectives = "Gather 5 Wolf Skirt Steaks from Dire Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26621] = { id = 26621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection", description = "The weapons the Horde has supplied us with will be more than enough. The four of us should split up and arm as many Dragonmaw workers and merchants as we can.\n\nDon't underestimate us, {name}. You'll find even our tradesmen are ferocious in battle.\n\nLet's do as much damage as possible. Arm a squad of Dragonmaw and lay waste to the fel enforcers and warlocks that have intimidated my people for so long. Then meet back here to launch our final strike!", progress = "Revolution, at last!\n\nThe Dragonmaw are finally undoing the shackles of the filth who have held us back!", completion = "We've lost a lot of good orcs, but the fight is going our way, {name}.\n\nMor'ghor's regime is collapsing. All that remains is to destroy the beast himself.", objectives = "Arm 3 Dragonmaw Workers or Merchants, then slay 10 Dragonmaw Enforcers and 4 Dragonmaw Warlocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26622] = { id = 26622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Mor'ghor", description = "The time has come. Mor'ghor dies today.\n\nBe warned, {class}. Demon blood courses through his wretched veins, and he channels unnatural power. He will be destroyed, yes. But it will not be an easy fight.\n\nYou remember where Mor'ghor resides, at the top of the camp. I will meet you there. Finish him!\n\nBe sure to recruit 3 Dragonmaw followers if you are short - you will need our help.", completion = "Well done, {name}! You have done the Horde proud in my absence.\n\nThe Dragonmaw have joined us, with Zaela as their new leader. Blood was shed, but casualties were low, and we have their complete loyalty.\n\nOur Horde grows stronger!", objectives = "Slay Warchief Mor'ghor in Dragonmaw Port. You can still recruit Dragonmaw Merchants and Workers to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26623] = { id = 26623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider meat!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!\n\nIf you want to try some still, I'm afraid I'm out of meat. I need some lump meat to whip up a few more cakes.\n\nVenom Web Spiders are a good source - they nest to the north, between the foothills and the river.", progress = "Hail, {name}.  Did you get that lump meat for me?", completion = "Ah yes, a nice lump you have there!  Let me just get this seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good.", objectives = "Gather 6 Dusky Lumps from Venom Web Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26624] = { id = 26624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting In With the Bloodsail", description = "These plans are... interesting.  Firallon, you're smarter than this!\n\nLook, he has all three ships devoted to cannon fire, and only a few men coming in through the tunnel.  He can never take Booty Bay with three ships and a dozen footmen.  And he knows that.\n\nNo, they've got something else planned... and you're going to find out what it is.  Speak to Yancey Grillsen, the Bloodsail Recruiter, just to the north of town.\n\nThat's right, {name}.  You'd better hope that they don't recognize your face.", completion = "Yarr, ya made a good decision, lad.", objectives = "Report to Yancey Grillsen at the waterfall north of Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26625] = { id = 26625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggzor the Earthinator", description = "You have to put an end to this now!\n\nGo back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", progress = "Is he dead? Do you have the cudgel?", completion = "<Gravel solemnly nods his head.>\n\nFinally, we can move forward and rescue the Stonefather.", objectives = "Obtain the Earthinator's Cudgel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26626] = { id = 26626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have a Situation", description = "One of Clay's catapult teams is broken down on the front. I need you to get some parts from him and get that catapult back in the fight, {name}.", sourceObjective = "Speak with Clay Mudaxle on the Fractured Front in Deepholm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26627] = { id = 26627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit", description = "I've been told there's signs of activity at Beggar's Haunt. People have reported seeing lights in the tower to the east of town.\n\nFew would be bold enough to stay that close to Deadwind Pass. You're the first to report since I've learned about this; go check it out and make sure whatever's in there is human.", completion = "Ah, welcome, stranger. I'd offer you something, but there's not much here...\n\nCould I beg you to run some errands for a poor old hermit?", objectives = "Find the denizen of the tower at Beggar's Haunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26628] = { id = 26628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, {name}?", completion = "We survived the attack!\n\nWe could not have done it without you, {name}.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny {race}....", objectives = "Protect Shakes O'Breen during the attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26629] = { id = 26629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Where Your Loyalties Lie", description = "Thar be just one thing...\n\nYancey hears things.  A few o' me hearties were pretty deep in their cups when they told me about some {race} {class} that came a-rollin' through the Southern Command lookin' for charts and orders.  Even ran a couple o' good pirates through, <he/she> did.\n\nLike I said, they were up to their eyeballs in grog, but still... a buccaneer's gotta trust his ears.  So I've just got one small task for ye, one sent down from Firallon hisself...\n\nBring me the head of Fleet Master Seahorn.", progress = "Firallon special-ordered this one himself.  Said the tauren's too much of a risk.", completion = "Well blow me down!  Now there's something ya don't see too often.\n\n<Yancey reaches out and shakes your hand.>\n\nWelcome aboard, {name}.  Plunder and booty await ye.", objectives = "Obtain the Head of Fleet Master Seahorn in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26630] = { id = 26630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looks Like a Tauren Pirate to Me", description = "Firallon wants MY head?  Now that's interesting.  But it's nothing we can't work around.\n\nThis Yancey character probably doesn't know my face too well.  Most non-tauren find us tauren indistinguishable from one another.  In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature.\n\nRikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats.  Get a replacement head and a hat, then return with both.", progress = "You should know that most tauren would find this shameful.  I find it... amusing.", completion = "That should fool that Bloodsail dimwit.\n\nThis was fun, {name}.", objectives = "Obtain a Cow Head and an Oversized Pirate Hat, then bring them back to Fleet Master Seahorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26631] = { id = 26631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Day as a Pirate", description = "Ye may be a slayer of Fleet Masters, but rules is rules and orders is orders.  And MY orders say that all new pirates start out as swabbies.  It's the rule.\n\nYou're to be working for Captain Keelhaul, the commander of the Riptide.  It's the westernmost ship in the fleet, which is parked south of the tip o' the cape.\n\nFind him in his captain's chambers, and bring yer papers.", progress = "I trust y'got yer papers, swabbie.  I'd hate t'send ye all the way back to Yancey.", completion = "Yes... yes... I see... well, everything appears to be in order.\n\nSlayer of the great Seahorn, eh?  That doesn't matter on MY ship.  Only thing you're gonna be slaying is deck stains.  Grab a mop.", objectives = "Bring Yer Papers to Captain Keelhaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26632] = { id = 26632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Escort", description = "Alright, I think I've got it working again. You've got to get the catapult to the stone trogg town, Needlerock Slag, just to the north of the front.\n\nThe driver will go with you. I'll head back and let Gravel know.\n\nThere's no doubt that the stone troggs will try to stop you. You just keep them off of the catapult. It packs a big punch.\n\nLet me know when you're ready, {name}.", completion = "<The catapult chief gives you an appraising look.>\n\nWord of your prowess has spread ahead of you, {race}. Let's see if you can help us keep these fungal horrors off of the front.", objectives = "Escort the Earthen Catapult safely to Needlerock Slag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26633] = { id = 26633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swabbing Duty", description = "I want the surface of the Riptide t'shine like a star ruby, Swabbie {name}.  I keep a tight ship around here, and it's swabbies like you that make it happen!\n\nWell, what're y'waitin' for, y'cockle-brained bilgerat?  Head updecks and start swabbin'!", completion = "I heard the most furious mopping sounds from down here, mate.  That's EXACTLY what your Captain likes to hear.", objectives = "Pick up a Swabbie's Mop on the deck of the Riptide, then keep the deck clean for 2 minutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26634] = { id = 26634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bane of Many A Pirate", description = "Gum disease.  It's a real problem, {race}.\n\nI know you're new and all, and probably haven't ever needed your gums cut, but the rest of us pirates have to deal with a little thing called SCURVY.  It's why we keep so many limes around here.\n\nWell... we used to keep limes around here.  Someone made off with our last shipment, but they can't have gone far - maybe to the nearby islands?  Bring them back, and maybe I'll see what I can do to get you promoted from swabbie.", progress = "I've seen too many good men die to such a preventable disease, {race}.  We need those limes.", completion = "I'll distribute these right away, {race}.  And I'll see what I can do to put in the good word for you.", objectives = "Obtain 5 Bushels of Limes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26635] = { id = 26635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball Swim", description = "Help out a fellow swabbie?\n\nKeelhaul asked me to gather up some cannonballs at the bottom of the ocean.  Let me tell you why this doesn't work for me.\n\n- One: I have tiny arms.  Look at them!  Do you really think I can pick up a cannonball, even underwater?\n\n- Two: I have a weak respiratory system.  I start to white out after holding my breath for more than ten seconds.\n\n- Three: There are sharks.\n\nYou gotta help me, {name}!  I've been demoted as far as I can... I don't want to see what comes next!", progress = "I wasn't always a swabbie, you know.", completion = "Thanks, {name}.  I'd been hearing whispers about \"Pretty Boy\" and a \"boo-box\".  I don't think I want to go in the boo-box.", objectives = "Obtain 6 Bloodsail Cannonballs from the water beneath the Riptide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26636] = { id = 26636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bravo Company Field Kit: Camouflage", description = "We're gonna need some supplies before we take out the Blackrock army and save Redridge. That's where you come in, rookie.\n\nKeeshan put me in charge of getting camouflage together for the Bravo Company field kit. What I need you to do is head south and do a little \"gardening.\" There are two parts to this little adventure that you should know about: (1) Leaves and (2) Fox poop. We need 'em both.\n\nWhat did you think camo was made of?\n\nHead south and gather what I asked for, <pal/lady>.", progress = "Leaves and poop - that's what I need.", completion = "Nice job, rookie. I'm gonna go ahead and put the camo in the box. We should be ready soon.", objectives = "Gather 5 Piles of Leaves and 5 pieces of Fox Poop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26637] = { id = 26637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bravo Company Field Kit: Chloroform", description = "The first part of this mission is all covert ops, {name}. To that end, we need to be able to incapacitate the enemy without making any sounds. To do that we're going to need chloroform.\n\nThe muckdwellers at the bottom of Lake Everstill hold chloroform in their glands. I'm going to need you to go underwater and recover muckdweller glands. Think you can handle it?\n\nCome back to me once you've recovered enough glands.\n\nWhere's the lake you ask? Open your eyes, dummy. Directly west.", progress = "Did you recover the glands?", completion = "Perfect. Those orcs won't know what hit 'em - literally. I'll need a few minutes to get these in working order and then I'll put them in the Bravo Company field kit.", objectives = "Collect 8 Muckdweller Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26638] = { id = 26638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Hunters", description = "Just south of here on the Lakeridge Highway are a group of Blackrock orcs that stalk the forests under cover of darkness and ambush the uninitiated. That group is the first line of defense for the Blackrock army. They're scouts, reporting everything they see back to their central command. They need to be taken OUT or our mission here could be compromised.\n\nHead south and kill every Blackrock hunter that you see.", completion = "Great work, {name}. We need to move quickly before they send for reinforcements.", objectives = "Kill 8 Blackrock Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26639] = { id = 26639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Point of Contact: Brubaker", description = "Before we do a damned thing we need to get a field kit together. You'll help with that, {name}. There's also a matter of scouting. Thankfully for that we got some help from Stormwind. An old war buddy of mine, Brubaker, was sent here by SI:7 to scout around for us. You're to meet him in the field, just south of here.\n\nMeet up with Brubaker and find out what he knows.", completion = "Brubaker is dead. It looks like the orcs are attempting to send a message with this grisly display. Upon closer examination you notice something in Brubaker's pouch.", objectives = "Find Brubaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26640] = { id = 26640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unspeakable Atrocities", description = "<You unfold the note and begin reading.>\n\nKeeshan, if you're reading this note, I'm dead. Likely that my position was compromised.\n\nOrcs are committing unspeakable atrocities against their prisoners. Yes, prisoners, Keeshan. They've got cages full of P.O.W's. If you're gonna blow up this valley, you'll need to free the prisoners first.\n\nTell my wife I love her and to take out the damned trash.\n\n-Brubaker\n\nPS - They've got black dragons.\n\nTake Brubaker's report back to Keeshan.", progress = "They got Brubaker?", completion = "<Keeshan reads the report.>\n\nDAMN IT! This just got complicated. We've got prisoners of war to rescue before we can blow up the valley. Not to mention the orcs have black dragons on their side.\n\nAre you ready, {name}?", objectives = "Deliver Brubaker's Report to John J. Keeshan at Camp Everstill in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26641] = { id = 26641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Make An Omelette Without...", description = "The Vilebranch broodguards to the northeast tend the eggs of Shadra's brood. Even if we kill the Vilebranch, those eggs will still sit there, waiting to hatch and release those horrible creatures further into the wilds.\n\nWe need to take care of this properly. Tear any eggs you see out of the egg sacks and bring them to me. Don't try to destroy them on your own; you might let the little ones out.\n\nWhen you get them back here, I'll see that they're properly disposed of!", progress = "Do you have the eggs?", completion = "I'll see these are burnt to ash right away, and scattered to the winds for good measure.", objectives = "Collect 5 Shadraspawn Eggs from Agol'watha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26642] = { id = 26642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Barrens", description = "For years, the Barrens have been the heart of the Horde presence on Kalimdor, a vital link between the orcs of Durotar and the tauren settlements in Mulgore.\n\nIn the chaos of the cataclysm, floods, earthquakes, and even a quilboar invasion threaten to separate us from this vital grassland.\n\nYou look ready for a challenge. Report to Kargal Battlescar at Far Watch Post and ensure the route to the Barrens remains clear! Head west from nearby Razor Hill and cross the Southfury River to find him.", completion = "A fresh recruit from Orgrimmar is it?\n\n<Kargal sizes you up.>\n\nI'll take what I can get. Keeping the roads open has been a nightmare.", objectives = "Report to Kargal Battlescar at Far Watch Post in Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26643] = { id = 26643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starvation Diet", description = "The Creeping Ruin to the east is crawling with fully-grown Shadraspawn spiders. They're large enough to drag off an entire dwarf in the night, and you'll see evidence enough of that when you get there... bodies are cocooned all through the ruins.\n\nThey don't keep them alive for long, {name}, but they feed off the bodies for days. It's too late to save the victims, but we can't let those spiders grow fat and thrive. Make sure you get rid of those cocoons.", completion = "A grim task for sure, {name}, but it'll keep the spiders left alive from recovering. I thank you.", objectives = "Destroy 6 Cocooned Victims at the Creeping Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26644] = { id = 26644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attracting Attention", description = "Swabbie {name}!  This is a sad day fer ol' Cap'n Keelhaul.  Today I lose m'best swabbie.\n\nA letter's come in from Fleet Master Firallon.  Apparently he's heard about the excellent swabbin' y'been doin', and he wants t'take ye aboard the Crimson Veil as his Jack o' Swords and third mate.  She's moored just next t'the Riptide.\n\nPiracy career-wise, this's a big step fer ye, Swabbie {name}.  I recommend y'take his offer.\n\nDismissed!", completion = "So ye be the one that did ol' Seahorn?  Yancey sent word, but I wanted to make sure he hadn't been telling his tall tales again.\n\nI'll make it brief.  Ye did well on Keelhaul's crew, but I expect ye to do even better on mine.  I've got an entire fleet to attend to, so you'll be helpin' to run the day-to-day of me ship.\n\nWelcome aboard the Crimson Veil, sailor.", objectives = "Report to Fleet Master Firallon within the Crimson Veil in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26645] = { id = 26645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Watch", description = "I'm afraid you're all I've got to help here, {name}. Stormwind's forces are so taxed by greater evils that they can't spare a single footman to protect Darkshire. It's up to me and the rest of the Night Watch to keep our homes safe.\n\nThere's more threats here than just wolves, unfortunately. Rotting horrors roam near Blind Mary's Haunt, on the southeast outskirts. If they're not kept in check, they'll be visiting our homes in the night.\n\nDeal with the undead and report back to me for your bounty.", progress = "I don't have authority to order you around, {name}. But at least think of the citizens here who'll be suffering if those undead are allowed to lurk.", completion = "Splendid, {name}.  For your service to the people of Darkshire you shall be rewarded.", objectives = "Kill 8 Rotting Horrors near Blind Mary's Haunt, southeast of Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26646] = { id = 26646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of War", description = "The Bravo Company field kit is ready, {name}. I'm gonna equip you with it and you're gonna enter Render's Valley, southeast of here, and free our P.O.W.s.  I'm sending Jorgensen with you to watch your back.\n\nNow the prisoners are being held on the northeast side of the valley in a large cage, but the key to the cage is in a cave on the south side of the valley. You'll have to steal the key, create a distraction, and free the citizens.\n\nGood luck, {name}! I'll be in touch through the field kit.", completion = "<The radio on the Bravo Company field kit crackles.>\n\nLooks like the P.O.W.s are free. Time to initiate Operation: End All.", objectives = "Free the Prisoners of War locked up in the prison at Render's Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26647] = { id = 26647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ol' Blasty", description = "We've got some work to do.  How much experience have you got with cannons?  Hmm... really?  Well, how about with ancient, fallin'-apart pirate cannons?\n\nWe've got a few cannons updecks that work the old-fashioned way: you load one cannonball in at a time, aim, lock it into place, and fire.  Works well if you're tryin' to hit the side of a three-sailer... not so well for rowboats and the like.\n\nWhy don't you head upstairs and lob a few shots at Smilin' Timmy Sticks?", progress = "You look a little green, {name}.  You feelin' alright?", completion = "I like the cut of your gib, {name}.", objectives = "Practice using the cannon by hitting Smilin' Timmy Sticks 5 times with cannonballs from Ol' Blasty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26648] = { id = 26648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Mortal Enemies", description = "Hey, new <guy/girl>, take a look at this.\n\n<The dwarf flips up his eyepatch to reveal a living, functional eyeball.>\n\nI don't wear this patch because of any lost eye.  I wear it because this OTHER eye is so strong, the normal one was just weighin' it down.\n\nThis eye's good for seein' all kinds of things, like those masked hooligans that follow us around.  Fleet Master says that they've been spotted over on Jaguero Isle.  Once you get there, fire this flare gun, and I'll help you spot 'em.", completion = "Excellent work, {name}.  The eternal battle wages on, but we've tipped the scales in favor of the pirates today.  Firallon will be happy to hear the news.", objectives = "Kill 15 Ninjas on Jaguero Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26649] = { id = 26649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive-By Piracy", description = "Now that you know how to handle our cannons, it's time to hit some real targets!\n\nThe Venture Company has found gold to the north of here... a rare type they call \"Black Gold\".  More like a Black Spot if you ask me.\n\nWe're going to take that gold, but first, we need to get rid of those Venture Company goons.  I've got an oarsman who will take you out there.  Head off the ship down the gangplank and speak with him on the islet's northern shore.", progress = "Those goblins will learn the fury of the Bloodsail!", completion = "Ahahaha!  Blasted 'em clear off their rigging!  I'll drink to that!\n\nYou've got a bright future, kid.", objectives = "Speak with the Bloodsail Oarsman outside the Crimson Veil, then use the cannon to kill 75 Venture Co. Oil Workers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26650] = { id = 26650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damsel's Luck", description = "I know ye just arrived here on the Crimson Veil, but I need to send ye off on another task.  The Damsel's Luck is the third ship in me fleet, moored over to the east.  Her skipper - Captain Stillwater - is no longer with us.\n\nDamn those masked hoodlums!\n\nAnyhow, Ironpatch told me about yer heroics at sea, and I be runnin' low on quality brigands.  I think yer more than capable for this new duty.\n\nCongratulations, matey.  Ye be the new captain of the Damsel's Luck.", completion = "You see a set of plans unrolled on the table.  They explain everything!\n\nThese are the details of the impending attack on Booty Bay.  Battle formations, plans of attack, and something about a group called the \"Brashtide Crew\".", objectives = "Report to your Captain's Chambers within the Damsel's Luck in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26651] = { id = 26651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Win a War, You Gotta Become War", description = "<The Bravo Company radio beeps.>\n\nDo you understand yet, {name}? Do you now see what we gotta do to win a war against these monsters? YOU GOTTA BECOME WAR! NO MERCY!\n\nWith the P.O.W.s freed you're clear to plant the seaforium. Carefully make your way into each of the structures out there and plant a charge.\n\nPlant a seaforium charge at the Blackrock munitions hut and the Blackrock tower. Once you're done meet up with me and the rest of Bravo Company at Shalewind Canyon, east of Render's Valley.", completion = "And now, we blow the whole damned thing up.", objectives = "Use the Bravo Company Field Kit to plant a Seaforium Charge at the Blackrock Tower and Blackrock Munitions Hut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26652] = { id = 26652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror...", objectives = "Bring the Spectral Comb to Blind Mary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26653] = { id = 26653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some ghost hair thread?  You can get it from Madame Eva at her home on the Darkshire square.", completion = "Ah, ghost hair thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.", objectives = "Speak with Madame Eva in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26654] = { id = 26654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", progress = "I sense that you have seen Blind Mary.  You have my comb...?", completion = "I can make a spool of ghost hair thread with this, and have a few strands to spare.  Here are some coins for those extra strands.", objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26655] = { id = 26655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Thread", description = "Here is your thread, {name}.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", progress = "I need to string the ghost hair thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good {name}, take this as payment for your honorable deed.", objectives = "Bring the Ghost Hair Thread to Abercrombie in his tower at Beggar's Haunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26656] = { id = 26656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't. Stop. Moving.", description = "When Deathwing came, the Stone Dragons flocked to him. In his absence, they are again without purpose. They swarm and feed upon our kin.\n\nI have bound dozens of Opalescent Guardians, but am unable to lead them from the safety of cover. I need someone more swift, as I suspect you might be.\n\nLead them by ground towards Therazane's Throne to the east. Surely, some will not make it, but as long as you keep moving, you should be able to bring several to join our forces there.", progress = "Did they make it, {class}?", completion = "Well done. Of my main strengths, speed is not one.", objectives = "Rush at least 5 Opalescent Guardians east by ground, out of the Pale Roost, to the stone circle near Therazane's Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26657] = { id = 26657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Falls", description = "Stone Dragons bow only to strength. When we have punished them enough, they will bend back to our will.\n\nI have sent many of my strongest giants onto the fields in the west. They will bring the drakes to the ground. You will see to it that they do not take wing again after they fall.", completion = "Not just fast it seems. You have some bite in you.\n\nWell done, {class}.", objectives = "Kill 6 Stone Drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26658] = { id = 26658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragile Values", description = "It is now time to draw the Broodmother's attention. To do so, we will need a mallet that the troggs use when making offerings to her.\n\nSeek out the Stone Trogg Beast Tamers that are attempting to tame basilisks in the southern portions of the Pale Roost. You will find a mallet on one of their corpses.", progress = "Did you find a mallet?", completion = "Glorious.\n\nNow we will deal a blow to the stone dragons that they will remember for the next hundred years.", objectives = "Retrieve a Stonework Mallet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26659] = { id = 26659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonating Blow", description = "On the western edge of the Pale Roost, you will find a resonating crystal. Strike it with the mallet and the broodmother will come.\n\nBe ready for battle. I will be there to aid you, but she will not be easily overcome.", completion = "Impressive, fleshling. You are far more capable than I initially assumed.\n\nI will extend that sentiment to the Stonemother as well.", objectives = "Defeat Aeosera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26660] = { id = 26660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}.  These nights get cold, and I need that drink to put fire in my veins again!", completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it.", objectives = "Speak with Tavernkeep Smitts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26661] = { id = 26661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nrot blossoms grow in strange places.  They tend to flourish on dead things, and Duskwood has its fair share of those!\n\nI've seen a few of them growing at Tranquil Gardens Cemetery lately. Check near the graves... but mind the dead that are walking about near there.", progress = "Hi, {name}.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.\n\nI'll whip up the zombie juice... it's strong stuff, I warn you.", objectives = "Gather 5 Rot Blossoms from Tranquil Gardens Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26662] = { id = 26662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brashtide Crew", description = "The charts mention a group called the Brashtide Crew.  This name is new to you, though you've heard about a few other newcomers to the Buccaneers.\n\nMaybe it's time you paid them a visit and found out what they know.", completion = "The Brashtide Crew aren't just pirates... they're worgen pirates!  And they're joining in on the attack!\n\nRevilgaz is definitely going to want to know about this.", objectives = "Speak with Long John Copper on the Damsel's Luck, Enormous Shawn Stooker on the Crimson Veil, and Wailing Mary Smitts on the Riptide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26663] = { id = 26663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinking From Within", description = "The attack on Booty Bay is looming.  You'll have to return to Booty Bay quickly and inform the Baron.\n\nFirst, however, it might be a good idea to sabotage some of the pirates' supplies while you're still in their favor.  The pirates keep most of their supplies belowdecks, spread out across the entire fleet.", completion = "You've set the pirates back several days' work.  Hopefully this will delay their attack.", objectives = "Sabotage the Barrel of Grog, the Barrel of Gunpowder, and the Crate of Cannonballs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26664] = { id = 26664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Mutiny", description = "Before returning to Booty Bay, you should do everything you can to weaken the Bloodsail Buccaneers.  Unfortunately, even as captain, you're prohibited from killing other buccaneers in cold blood.  Only a Fleet Master can do that.\n\nYou can, however, put mutineers to the sword... and mutiny can be awfully hard to disprove.\n\nSpeaking of which, those Bloodsail corsairs that hang out on the lowest level of the ships have been acting awfully suspicious...", completion = "The fewer Bloodsail Buccaneers that Booty Bay has to fight, the better.  However, it might be best to stop slaughtering your supposed allies before you draw suspicion to yourself.", objectives = "Accuse 9 Bloodsail Corsairs of mutiny, then kill them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26665] = { id = 26665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Booty", description = "You feel like you've done just about enough damage, and you know the Bloodsail's battle plans.  You've done everything that Baron Revilgaz has asked of you.\n\nIt's time to hang up the pirate hat and return to Booty Bay.  The battle looms near.", completion = "The Brashtide!?  I thought they were dead and gone YEARS ago!\n\n<Revilgaz listens intently as you relay the information you gathered.>\n\nNo, that absolutely makes sense.  And it's not good news either.  The Brashtide are formidable foes, and if their numbers are anywhere near what they were before they disappeared, we're in for a nasty battle.", objectives = "Report to Baron Revilgaz at Booty Bay in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26666] = { id = 26666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "I'm here because I received a letter from my brother Stalvan, who I haven't seen in years. On arriving here, I was told he was dead...\n\nThe entire town refuses to offer any further explanation. Any mention of his name is met with terror and suspicion. As if I didn't have enough of that myself!\n\nI'm afraid of what will happen if my frustration and anger grows any further. I beg you, help me get to the bottom of this. Implore Clerk Daltry for any information he may have on my brother.", completion = "Can I help you?", objectives = "Seek out Clerk Daltry in the Darkshire Town Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26667] = { id = 26667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Letters", description = "You want to know about Stalvan...\n\nYou're not the first, you know. We get outsiders coming through asking about him every so often. Always outsiders. Everyone who lives here knows better.\n\nYou're out of luck, anyway. I'm missing half the archives. Feral worgen broke into the town hall not a few nights ago and tore the place to shreds.\n\nThe documents you'll want are probably strewn all across Brightwood Grove by now, deep in the woods to the west. Not worth it if you ask me.", progress = "Look, sir, I really don't want any trouble...", completion = "By the Light... you actually went and got it?\n\nI'm shocked. I suppose I owe you thanks for returning it to the archives.", objectives = "Collect the Bundle of Shredded Letters from Brightwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26668] = { id = 26668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation", description = "Those explosives you planted were high yield, {name}. When I push this button on the Bravo Company field kit, that whole valley is gonna be consumed by a massive fireball of death.\n\nYou know, I think you should do the honors. You did all the hard work, after all.\n\nReady?", completion = "Did you see those orcs explode? THAT'S HOW WE DO IT IN BRAVO COMPANY! Now to clean up the rest of these jackasses.", objectives = "Blow up Render's Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26669] = { id = 26669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In A Dark Corner", description = "If you're that serious about this, I'll help you, {name}. I know where the other documents must be. I'm just too terrified to do anything about it.\n\nThere's only a few places that those horrible Nightbane beasts gather when they're not prowling the forest. One of them's the Rotting Orchard to the south. They use the buildings there as their dens, so if they haven't just eaten the other documents, you might find one there... but you'll have to search their lairs thoroughly, I wager.", progress = "You're back in one piece, I see.", completion = "This was all you found?\n\nThat's bad news, I'm afraid...", objectives = "Search the Rotting Orchard for the Torn Journal Page.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26670] = { id = 26670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roland's Doom", description = "This isn't all of it...\n\nYou should let it go, {name}. The only place left to look is Roland's Doom. That's the mine south of town, and the largest lair of worgen in Duskwood. Nobody in Darkshire has ever made it back from that place alive. In fact, some of the records I have here imply that's where the monsters first came from... who knows what evil's lurking in there?\n\nPlease, {name}, just give it up. Let's just forget about this whole thing, and never speak of it again.", progress = "I told you, {name}, it's not worth pursuing...", completion = "You actually went and got it?!\n\nI don't know whether to call you brave or insane. But once again, my archives thank you.", objectives = "Search Roland's Doom for the remaining pages of Stalvan's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26671] = { id = 26671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Stalvan Mistmantle", description = "You've recovered everything. Everything except the last page...\n\n...which I've got right here. Don't look at me like that. You'll understand when you read it. Some even say it's cursed, you know. In fact, I was relieved when the worgen broke in and made off with these!\n\nTake it. Take all of it, in fact. I thank you for recovering my archives, but I don't want anything to do with this ever again. Please, just leave me be.", progress = "You're back! Did you find anything about my brother?", completion = "I can't thank you enough... I had hoped for this to be a joyous reunion, but the more I learn, the less glad I am to have asked.\n\nBut I must know.", objectives = "Take The Legend of Stalvan back to Tobias Mistmantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26672] = { id = 26672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clawing at the Truth", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>\n\nI must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", progress = "What dark whispers guide you to my door, {class}?", completion = "How interesting. It's been quite a while since I've seen such a ring...", objectives = "Bring the Mistmantle Family Ring to Madame Eva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26673] = { id = 26673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BREADCRUMB", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>I must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", objectives = "Bring the Mistmantle Family Ring to Madame Eva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26674] = { id = 26674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistmantle's Revenge", description = "I'm afraid I cannot give Tobias the answers he seeks. But I can help you find the only person who can...\n\nStalvan Mistmantle.\n\nTake the ring into the woods to the north, to Manor Mistmantle, where Stalvan's body was buried. Enter, and hold the ring before you. Let the waning moon pour its light through the ring, and the spirits will answer your call.\n\nTake heed, {name}. The questions of the living can offer more comfort than the answers of the dead.", completion = "Master Harris may have been right. I would have been better to leave the past behind.\n\nI've got a new life now. Whether it's that of a monster or a man is up to me.\n\nAs for you, I cannot thank you enough for your assistance, regardless of the outcome. Please, take this with my thanks.", objectives = "Use the Mistmantle Family Ring at Manor Mistmantle, north of town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26675] = { id = 26675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Value of Trust", description = "The troubles of this world seem to never fade. They shift, change, and reform, but they are ever-present.\n\nThe wind brought us whispers of a traitor in our midst. We sent one of our best sentinels to investigate, and now she has turned up dead. I did her disservice in assuming that the traitor would not be aware of our movements... I was brash, and she paid for my folly.\n\nI need a new face to pick up the trail. Someone the people of the city won't know. This is a dangerous request. Will you help me?" }
quests[26676] = { id = 26676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, {name}.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude.", objectives = "Bring the Zombie Juice to Abercrombie at Beggar's Haunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26677] = { id = 26677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghoulish Effigy", description = "Out here on the outskirts of town, it's a wonder the walking dead haven't eaten me!  In fact, just yesterday a pack of ghouls was pounding on the walls of my tower!\n\nI want to make an effigy - a kind of \"scarecrow\" for ghouls.  To do that I need some ghoul ribs.  You can find plenty of them on the fetid corpses wandering Manor Mistmantle's grounds, north of Darkshire...\n\nGet the ribs for me, and I will repay you with some coin.", progress = "I'm sure you could find plenty of ribs in Raven Hill as well, but you might not want to wander so far at night...", completion = "Ah, thanks.  These will do just the trick!", objectives = "Gather 7 Ghoul Ribs from Fetid Corpses at Manor Mistmantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26678] = { id = 26678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doublerum", description = "<Baron Revilgaz sighs.>  Even with all my suspicions about Firallon's plot, we aren't prepared for a full two-front attack between the Bloodsail and the Brashtide.  It's going to take a small miracle to hold Booty Bay today.\n\nI've got a barrel of Doublerum in my chambers.  Take the stairs down three flights, and check the first door on your right.  You can ignore the warnings on the barrel... those should be the least of your worries.", completion = "This must be the doublerum.  You pour a glass for Revilgaz, then consider pouring one for yourself...", objectives = "Find Baron Revilgaz's Barrel of Doublerum within Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26679] = { id = 26679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Revilgaz", description = "Something is happening outside.  Could the Bloodsail already be here?\n\nYou'd better get Revilgaz his doublerum.  Quickly.", progress = "Guess who showed up while you were gone?", completion = "<The Baron quickly empties his cup.>\n\nAH!  Much better, {name}.  Now, let's get down to business.  I believe that you and I have a town to save.", objectives = "Bring the Doublerum to Baron Revilgaz at Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26680] = { id = 26680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, {name}, retrieve this crate for me for I miss it sorely.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, {name}!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!", objectives = "Return Abercrombie's Crate to Abercrombie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26681] = { id = 26681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", progress = "A letter? What's this all about?", completion = "<Ello looks at the letter, and immediately pales.>\n\nYou fool! You've doomed us all!", objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26682] = { id = 26682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shambling Threat", description = "Dustwallow is Horde territory, {name}. The humans may have their little island and their precious sand bar, but the marsh belongs to us.\n\nIn time, we will surely win this stalemate with the humans. For now, we must master our own territory. The withervine bog beasts to the north rise from the marsh itself to attack any living thing that approaches. If we own this marsh, we must not let our own land fight back against us!\n\nSlay the bog beasts, if you wish to serve the Horde. You will be rewarded.", completion = "Well done, {name}. We'll be able to focus on greater threats here now.", objectives = "Slay 7 Withervine Creepers or Withervine Ragers in the marsh north of Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26683] = { id = 26683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look To The Stars", description = "My gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars. According to Cog's blueprint, what I need first is a way to reflect light.\n\nI remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", completion = "Why yes, I used to own a looking glass.", objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26684] = { id = 26684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Insane Ghoul", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an insane ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!", objectives = "Retrieve Mary's Looking Glass from the Insane Ghoul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26685] = { id = 26685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classy Glass", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, {name}.  Now I can continue my research. . .", objectives = "Kill Zzarc'Vul in the southern ogre mound in Duskwood and collect the Ogre Monocle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26686] = { id = 26686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones That Walk", description = "There's even fouler undead left to deal with, {name}.\n\nTranquil Gardens Cemetery, further south of town, is a place you don't want to be caught in at night. The bones that rise from the ground there are cunning enough to remember how to swing an axe or cast a spell.\n\nI shouldn't need to explain how dangerous that makes them. Proceed with caution, but remember the people of Darkshire that will suffer if you falter.", completion = "The people of Darkshire thank you, {name}.  You have proven yourself to be a great ally of The Night Watch.", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 5 Skeletal Warriors and 5 Skeletal Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26687] = { id = 26687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements From Theramore", description = "Hawthorne dead... my own son murdered... the situation in the Barrens is out of control, {name}.\n\nI'm going to take charge of Fort Triumph and try to lock things down. To do that, I'm going to need reinforcements. Reinforcements that were promised from Theramore weeks ago!\n\nTravel to Theramore in Dustwallow Marsh and give Captain Garran Vimes an earful. What good is that blasted road through the swamp if the men and materiel aren't rolling in?", completion = "What now, soldier?\n\nReinforcements? For the Barrens? We've been bleeding supplies and men there for months!\n\nDoes someone need to remind Twinbraid of the attack on Northwatch? Our losses at Honor's Stand? What happened to the men I sent to Fort Triumph? We've nothing to spare!\n\nListen {name}, if you want to help out our cause, you'll focus your efforts here in Dustwallow. Between the deserters and the Horde encroachment... we could use a hand.", objectives = "Travel to Theramore Isle in Dustwallow Marsh and talk to Captain Garran Vimes in the main barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26688] = { id = 26688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane worgen in Brightwood Grove. We'll see if you have what it takes to hunt these monsters.", completion = "Impressive, {name}. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.", objectives = "Kill 7 Nightbane Worgen in Brightwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26689] = { id = 26689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rotting Orchard", description = "The worgen infestation stretches further than Brightwood Grove. To the south, on the very edges of Darkshire itself, the Rotting Orchard is host to even more of the savage beasts.\n\nThe worgen there are more cunning, {name}, but just as savage and evil. They conjure foul shadows to tear their enemies apart from a distance. Go to the Rotting Orchard, and slay the Shadow Weavers to keep the town safe!", progress = "Back so soon, {name}? I hope you haven't come to tell me you've given up.", completion = "You performed well against the Shadow Weavers, {name}. But even now, years after their first arrival, there seem to be so many to replace the ones we kill.\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem.", objectives = "Kill 10 Nightbane Shadow Weavers at the Rotting Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26690] = { id = 26690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile and Tainted", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", progress = "Intimidating beasts aren't they? But have no fear, {name}, those who stand for the Light will never fall!", completion = "{name}, to be honest with you, I did not believe that you would get this far, but you are clearly a {class} to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation.", objectives = "Kill 8 Nightbane Vile Fangs and 8 Nightbane Tainted Ones in Roland's Doom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26691] = { id = 26691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Here you go, {name}. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, {name}, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, {name}, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light.", objectives = "Bring Calor's note to Jonathan Carevin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26692] = { id = 26692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowhide Extinction", description = "Now that every Blackrock orc south of Lake Everstill is nothing more than ash and cinder, we can turn our attention to the Shadowhide gnoll army of Galardell Valley, directly north of here.\n\nI want you to head out there and kill 'em all, {name}! Initiate Operation: Extinction, soldier. For Bravo Company and for the Alliance!", completion = "We're closing in on the Blackrock high command. There's nowhere left for those dogs to run.", objectives = "Kill any 20 Shadowhide Gnolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26693] = { id = 26693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Tower", description = "We got lucky with some vital intelligence from the locals of this valley. Those two behind us, the Ranthals, have informed me that the gnolls in Galardell Valley are being controlled by a powerful magus in the tower of Ilgalar. The problem is that the tower is sealed by a magical force field.\n\nThe first thing we need to do is get the key that will get you inside. The gnoll general, Fangore, has your ticket inside. Kill General Fangore and get the key.\n\nI'll be in touch.", progress = "I hear you loud and clear, {name}.", completion = "<Keeshan comes in over the Bravo Company field kit.>\n\nNow that the easy part is over, it's time for phase two.", objectives = "Recover the Key of Ilgalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26694] = { id = 26694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Magus Doane", description = "<The Bravo Company field kit vibrates.>\n\nGood work, kid. I've got some vital intel for you. The magus in the tower is a human named Doane. Damned traitor is working for the Blackrock orcs. I want him dead.\n\nUse the key of Ilgalar and get inside that tower. Work your way to the top and show Doane what Bravo Company does with traitors.\n\nRendezvous back at Shalewind Canyon when the deed is done.\n\nKeeshan, over and out.", progress = "I hear you loud and clear, {name}.", completion = "He teleported away? Mentioned Darkblaze? What the hell is going on here.\n\nLooks like it's time to strap in and finish this nonsense.", objectives = "Kill Grand Magus Doane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26695] = { id = 26695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Takeoff", description = "I've got an idea, but it's going to involve some footwork on your part.  As a goblin cartel, the Blackwater Raiders have a lot of explosives on hand.  In fact, I know for a fact that our old friend Narkk keeps a case in the back of his shop, in the Old Port Authority.\n\nGo grab them and bring them here, if they haven't already exploded.", progress = "You're still alive?", completion = "You brought them!  I'm beginning to think the tide is turning in our favor, {name}.", objectives = "Obtain Narkk's Handbombs from the Old Port Authority inside Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26696] = { id = 26696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Kalimdor", description = "Say, you haven't seen a fish about this long?  Short fins?  Responds to the name Steve?  He's blue?\n\nNever mind, I'll keep looking.\n\nActually... there was another reason I came here to Booty Bay.  Boss Krog, over in Dustwallow, is looking for new blood.  Someone to help us Stonemaul from getting overrun.  You look strong enough.\n\nWait on the edge of the pier for the next ship, then ride to Ratchet.  Gazlowe should be able to help you from there.\n\nSteve?  Steve!", completion = "Yeah?  What can I do for ya?", objectives = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26697] = { id = 26697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Voyage of the Brashtide", description = "We'll never survive this attack with all these worgen pirates pouring into the harbor from the north.  Luckily, it looks like they're not armed with cannons, so if we can get you out of the harbor, you can attack from the skies.\n\nKebok, the Horde flight master's assistant, is right around the corner.  Talk to him and let him know that you're going to need his bravest wind rider.\n\nBring a couple armloads of handbombs with you.  You'll need all of them to stop those attack boats!", progress = "We're still overwhelmed, matey.  Get back out there and protect my town!", completion = "I hope those mongrels know how to doggy paddle!\n\nActually, I take that back.", objectives = "Speak with Kebok in Booty Bay to board a Bold Wind Rider. Then use the handbombs to kill 85 Brashtide Crewmen and destroy 6 Brashtide Attack Boats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26698] = { id = 26698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Seahorn", description = "When the Brashtide pulled in, Seahorn grabbed the nearest weapon he could find and jumped off the ledge here.  You'll find him down below, probably pounding new holes into those worgen's skulls.\n\nHelp him out down there.  I can handle the motivation from up here.", completion = "I should have known these Brashtide were alive and up to no good.  I'd written them off years ago.", objectives = "Report to Fleet Master Seahorn in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26699] = { id = 26699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Brashtide", description = "The Brashtide are everywhere!  The Baron's Booty Bay Bruisers are no match for their sheer numbers, I'm afraid.\n\nWhile you're down here in the fray, why don't you help me get rid of a few of them?\n\nWhen you're done, don't bother coming back here.  I'll probably be pretty busy.", completion = "We need to keep moving, {name}.  Booty Bay won't hold out for much longer.", objectives = "Kill 10 Brashtide Raiders in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26700] = { id = 26700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damsel's (Bad) Luck", description = "I heard that this ship here is the Damsel's Luck.  Didn't you used to be the captain of that thing?  You must know your way around it, then.\n\nThe Brashtide are our main concern, but we still don't want to take an unnecessary pummeling from those cannons of theirs.  Grab this rope behind me and take out some of those angry-looking corsairs.  Check in with the Baron when you're done.", completion = "Attacking your former crewmen...\n\nYou really have grown into a real pirate, {name}!", objectives = "Kill 8 Bloodsail Corsairs in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26701] = { id = 26701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Brackenwall", description = "Listen, I got no special love for the Horde... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.\n\nThat two-headed ogre and his pet fish left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Krog.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", completion = "Lok'tar, {race}.  Welcome to Brackenwall.", objectives = "Speak with Bragok in Ratchet to fly to Brackenwall Village. Then report to Krog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26702] = { id = 26702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Theramore", description = "Listen, I got no special love for the Alliance... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.  Sometimes better.\n\nJeyne left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Calia Hastings.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", completion = "Welcome to Theramore.", objectives = "Speak with Bragok in Ratchet to fly to Theramore. Then report to Calia Hastings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26703] = { id = 26703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodsail's End", description = "We've nearly won the day, largely thanks to you.  One task remains, however... kill Fleet Master Firallon.\n\nIt looks like most of Firallon's crew is already dead, but I know that old sea dog well enough to know that he's not done yet.  No, he's cooped up tight in his cabin, ready to go down with his ship.\n\nSpeak with Kebok again to get a wind rider.  I'll try to hold off the cannonfire while you're on board.", completion = "{name}!  You're awake!  We found you bobbing in the harbor, shortly after the remaining attackers had turned tail.  We were worried about you for a while there...\n\nI've been meaning to thank you, {name}.  Not only did you provide us with the intelligence to prepare for this attack, but you helped fight off the Bloodsail AND the Brashtide.  Your name will always be remembered here in Booty Bay.\n\nWe here in Booty Bay pride ourselves on our booty.  Care to take first pick?", objectives = "Speak with Kebok in Booty Bay to get a wind rider, then kill Fleet Master Firallon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26704] = { id = 26704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26705] = { id = 26705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Town-In-A-Box Tracking Event" }
quests[26706] = { id = 26706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endgame", description = "We need to get rid of that flying gunship if our people have any chance of escaping.\n\nHere's the plan.  Keel Harbor had its share of rebel sympathizers in the old days.  I've managed to round up a hefty amount of incendiary explosives from one of our storehouses.\n\nWe're going to hit the enemy with a force small enough to fly undetected.  The night elf hippogryphs should do the trick.\n\nTobias will give you the signal when we're ready to go.", progress = "The only risks worth taking are the ones that lead to victories worth having.", completion = "We did it, {name}.  We've started the evacuation.  If we leave soon we'll leave the Forsaken fleet in the dust.", objectives = "Jump on a Hippogryph when Tobias signals you and destroy the Horde Gunship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26707] = { id = 26707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deadly Vine", description = "I need large amounts of corpseweed for Master Harris's concoctions. It's difficult to obtain, but we can't let our supply dwindle.\n\ncorpseweed is tough stuff to tangle with... the plant will get you before you get it, if you're not careful! But if you'd like to help out, I'll eagerly pay you for any you gather yourself.\n\nYou'll find plenty of it all over the Yorgen Stead to the southeast.", progress = "Do you have the corpseweed?", completion = "I thank you, {class}... and I'm sure the worgen that may be returned to sanity with the potion this will make would thank you too.", objectives = "Collect 5 pieces of Corpseweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26708] = { id = 26708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "I'm here to help you and Bravo Company end this mess. You're to get in the Bravo Company siege tank and clear a path to Keeshan's Post on the other side of the valley, north of here.\n\nThis is a high alert situation soldier as the Blackrock orcs are now aware of your location and sending a large force to meet you head on. Terminate them all with extreme prejudice.\n\nI'll see you on the other side. May the Light have mercy on your soul.", progress = "We're ready for the final assault.", completion = "The only thing left to deal with now are the orcs holding out at Stonewatch Keep.", objectives = "Use the Bravo Company Siege Tank to kill 200 Blackrock soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26709] = { id = 26709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Throne", description = "I am returning to my throne. I've no desire to see any more of these Earthen Ring, but you remain welcome here, {race}. If you wish to help us rebuild our realm, perhaps we can help you in return.\n\nAll things in time.", completion = "You returned. This is good. The Stone Lords have been asking after you.", objectives = "Seek out Therazane at Therazane's Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26710] = { id = 26710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost In The Deeps", description = "Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths.\n\nHe's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it.\n\nHe seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.", progress = "Pebble is much smarter than he lets on, but he is spoiled. I fear one day he may suffer for it.", completion = "You've done well. Now that these are rocklings are free to learn our ways, they will grow tall and strong.\n\nOne day, we will extinguish the gyreworm infestation from our realm, and these rocklings shall no longer be plagued in their youth.", objectives = "Find Pebble within the Crumbling Depths and lead him safely out of the tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26711] = { id = 26711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to the Bank", description = "Yo, baby. Wassup? You ready for the party?\n\nNo?! You know I love you, so I don't know how to say this, but check it... I think you need to swing into town to buy a new outfit for the party.\n\nDon't look at me like that... you want to look gooood, right? Don't you want to look super fine for me? I am your contractually-obligated boyfriend after all!\n\nSwing by the bank first and pull out plenty of macaroons. You don't want to buy any of that cheap stuff!", completion = "Oh, it's you, ma'am! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! {name} is here!\n\nHere are your macaroons, ma'am. Come back anytime if you need more.", objectives = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26712] = { id = 26712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to the Bank", description = "Hi, babe. Are you ready for the party?\n\nNo?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party.\n\nDon't look at me like that... you want to look your best? Don't you want to look good for me? I am your contractually-obligated girlfriend after all!\n\nMake sure you swing by the bank first and pull out plenty of macaroons. Don't buy any of that cheap stuff!", completion = "Oh, it's you, sir! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! {name} is here!\n\nHere are your macaroons, sir. Come back anytime if you need more.", objectives = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26713] = { id = 26713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown at Stonewatch", description = "Only the Blackrock high command remains, {name}. They're all holed up in Stonewatch Keep, directly south of our position here at Keeshan's Post. I want you and the rest of Bravo Company to enter Stonewatch and put an end to the Blackrock orc invasion.\n\n{name}, no survivors.", progress = "This doesn't look good.", completion = "<The Bravo Company field kit beeps loudly.>\n\nCome in, {name}. Are you there? If you can hear me: Blackrock has the upper hand. I repeat. Blackrock has the upper hand. GET BRAVO COMPANY OUT OF TH...", objectives = "Kill Tharil'zun and Gath'Ilzogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26714] = { id = 26714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkblaze, Brood of the Worldbreaker", description = "As Troteman cuts out, the world around you grows eerily silent. In the distance you see a full grown black dragon!", completion = "<A single tear rolls down Troteman's left cheek.>\n\nThey died in defense of the Alliance. In defense of our kingdom! Heroes, all of them, and they will be laid to rest as such.", objectives = "Use the Horn of Summoning to call for Darkblaze. Defeat Darkblaze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26715] = { id = 26715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Stormrage", description = "I've spoken to Malfurion of your coming. He seemed very interested in meeting you himself.\n\nYou should go to him in the Temple of the Moon. You'll find him standing beside our beloved Tyrande Whisperwind, where he's remained diligently ever since his return.\n\nI must warn you... Malfurion has his reservations. You may be carrying a great burden for your people by being the one to meet with him.", sourceObjective = "Speak to Malfurion Stormrage in the Temple of the Moon in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26716] = { id = 26716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Privacy", description = "I greatly wish to speak with you, but I'd prefer a more intimate environment. One where we might have a bit of privacy from prying ears.\n\nIf you would, meet me in the Temple Garden in just a moment.", sourceObjective = "Meet Malfurion Stormrage in the Temple Garden in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26717] = { id = 26717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yorgen Worgen", description = "My kinsmen at Raven Hill are concerned with curing the feral worgen in these forests. The condition itself cannot be lifted, but sanity can be restored to those not too far gone.\n\nWhile most here have proven beyond help, we keep an eye out for those that retain vestiges of their minds... attachments to their old lives.\n\nI've seen a lone worgen lurking the Yorgen Farmstead, digging in a pile of dirt between the buildings...could you check out that pile and see if he's left anything?", progress = "Did you go look yet?", completion = "Sounds like a close call! But he ran off without harming you further...\n\nHe might be still fighting it. Master Harris must know!", objectives = "Examine the Mound of Loose Dirt at the Yorgen Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26718] = { id = 26718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb to Badlands", description = "Something bad happened." }
